window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[37]={"id":"037","numero":37,"titre":"Interruption volontaire de grossesse","objectifs":[{"id":"37-1","rang":"A","rubrique":"Définition","titre":"Connaître l’histoire politique et sociale qui a mené à la loi sur l’interruption volontaire de grossesse (IVG) de 1975","contenu":"<div class=\"notion-course\"><p>Repères chronologiques de l’<span>évolution</span> du <span>cadre légal français</span> autour de la contraception et de l’avortement, depuis la <span>loi Neuwirth (1967)</span> jusqu’à la <span>constitutionnalisation (8 mars 2024)</span>. Contenu strictement factuel et médico-légal.</p>\n\n      <table>\n        <thead>\n          <tr><th>Date</th><th>Évolution</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1967</strong> — Loi Neuwirth</td>\n            <td><span><span class=\"nc-green_bg\">Autorise la contraception</span></span> en France. Loi <strong>réellement appliquée à partir de 1974</strong> seulement (décrets d’application tardifs).</td>\n          </tr>\n          <tr>\n            <td><strong>Avant 1975</strong></td>\n            <td>\n              <strong>Avortement :</strong> acte <span>réprimé par la loi</span>, passible de prison.<br>\n              <strong>Conséquence :</strong> l’avortement clandestin n’avait pas disparu — il était responsable de <span>&gt; 250 décès/an</span> de femmes.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>17 janvier 1975</strong> — Loi Veil</td>\n            <td><span class=\"nc-green_bg\">Loi qui </span><span><span class=\"nc-green_bg\">dépénalise l’avortement</span></span><span class=\"nc-green_bg\"> est adoptée</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>1979</strong></td>\n            <td><span class=\"nc-green_bg\">Création des </span><span><span class=\"nc-green_bg\">centres d’IVG</span></span> pour permettre aux femmes de recourir à l’avortement dans un lieu approprié.</td>\n          </tr>\n          <tr>\n            <td><strong>8 mars 2024</strong> — Loi constitutionnelle</td>\n            <td>Inscription dans la <span>Constitution de 1958</span> de la <strong>liberté garantie des femmes de recourir à l’IVG</strong> → réaffirmation du caractère fondamental de cette liberté en France.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <span>loi Veil de 1975</span> ne légalise pas l’IVG, elle la <strong>dépénalise</strong>. La loi de mars 2024 a ensuite consacré la liberté de recourir à l’IVG dans la <strong>Constitution</strong> — la France est le 1er pays à inscrire cette liberté à son niveau constitutionnel.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":0},{"id":"37-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les causes de grossesses non désirées","contenu":"<div class=\"notion-course\"><p>Les <span>causes de grossesses non désirées</span> ne se résument pas à l’absence de contraception : <strong>2 femmes sur 3 (≈<span> 66 %</span>)</strong> ayant recours à une IVG <span>utilisaient une méthode contraceptive</span> au moment de la <span>grossesse</span>. Le problème tient donc surtout à un <strong>échec ou une inadaptation</strong> de la contraception.</p>\n\n      <h4>Les 3 causes officielles (CNGOF)</h4>\n\n      <ul>\n        <li><strong><span>Absence de contraception</span>.</strong></li>\n        <li><strong><span>Changement de méthode</span></strong> contraceptive — période de transition à risque.</li>\n        <li><strong><span>Méthode non adaptée</span></strong> — méthode peu efficace ou mal utilisée au regard du mode de vie (oubli de pilule, retard patch/anneau, retrait, méthodes naturelles…).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong>\n        <ul>\n          <li><span>&gt; 60 %</span> des femmes réalisant une IVG avaient une <strong>couverture contraceptive</strong> en début de <span>grossesse</span> → l’<strong>échec/inadaptation</strong> prime sur l’absence.</li>\n          <li>La <strong><span>grossesse</span> non désirée ne mène pas toujours à l’IVG</strong> : aujourd’hui <span>≈ 60 %</span> des femmes confrontées à une grossesse non prévue choisissent de l’interrompre, contre <span>40 %</span> en 1975.</li>\n          <li>La stabilité du nombre d’IVG ne traduit <span>pas un échec de la contraception</span>, mais une hausse de la propension à recourir à l’IVG en cas de <span>grossesse</span> non désirée.</li>\n        </ul>\n      </div>\n\n      <p><em>Complément hors fiche Notion (muette sur cet objectif) — Source : Collège CNGOF de Gynécologie-Obstétrique, 5ᵉ éd., item 37.</em></p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":0},{"id":"37-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître le nombre d’IVG réalisés en France","contenu":"<div class=\"notion-course\"><p>Chiffres-clés de l’<span>épidémiologie</span> de l’IVG en France (données <span>2019</span>) :</p>\n\n      <ul>\n        <li><strong>Nombre annuel d’IVG en France :</strong> <span>230 000 IVG</span> (en 2019).</li>\n        <li><strong>Tendance :</strong> <span>incidence</span> <span>relativement <span class=\"nc-red nc-bold\">stable</span></span>, avec <strong><span class=\"nc-red nc-bold\">légère augmentation</span></strong> en 2019.</li>\n        <li><strong>Rapport aux naissances :</strong> <span>1 IVG pour 3 naissances</span>.</li>\n        <li><strong>Proportion de femmes y ayant recours dans leur vie :</strong> <span>40 %</span>.</li>\n        <li><strong>Sous contraception lors de l’IVG :</strong> <span>&gt; 60 %</span> des femmes (= échec/défaut d’utilisation de la contraception, pas absence).</li>\n      </ul>\n\n      <h4>Géographie</h4>\n\n      <p>Zones où les <span>taux d’IVG sont les plus élevés</span> :</p>\n\n      <ul>\n        <li><strong><span class=\"nc-green_bg\">DROM</span></strong> (départements/régions d’outre-mer)</li>\n        <li><strong><span class=\"nc-green_bg\">Île-de-France</span></strong></li>\n        <li><strong><span class=\"nc-green_bg\">Sud-Est</span></strong><span class=\"nc-green_bg\"> (PACA, Corse)</span></li>\n      </ul>\n\n      <h4>Méthode</h4>\n\n      <ul>\n        <li><strong>IVG médicamenteuses :</strong> <span>70 %</span> des IVG, <strong>en hausse</strong> continue.</li>\n        <li><strong>Voie instrumentale (chirurgicale) :</strong> recours <strong>en diminution</strong> continue.</li>\n      </ul>\n\n      <h4>Délais et terme</h4>\n\n      <ul>\n        <li><strong>Délai entre 1ère demande d’IVG et réalisation :</strong> <span><span class=\"nc-pink nc-bold\">7,5 jours</span></span> en moyenne.</li>\n        <li><strong>Terme :</strong> <span>≥ 50 %</span> des IVG réalisées <strong>avant la 7ᵉ semaine de <span>grossesse</span></strong>.</li>\n        <li><strong>Hors structure hospitalière :</strong> <span>25 %</span> des IVG sont réalisées en ville.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":0},{"id":"37-4","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’âge de la population réalisant le plus d’IVG","contenu":"<div class=\"notion-course\"><p>Distribution par <span>tranche d’âge</span> du recours à l’IVG en France :</p>\n\n      <ul>\n        <li><strong>Tranche d’âge la plus concernée :</strong> <span><span class=\"nc-pink nc-bold\">20-29 ans</span></span>.</li>\n        <li><strong><span>Évolution</span> selon l’âge :</strong>\n          <ul>\n            <li><strong>&lt;<span> 20 ans</span> :</strong> <span>incidence</span> <span>en baisse</span>.</li>\n            <li><strong><span>20-25 ans</span> :</strong> <span>incidence</span> <span>stable</span>.</li>\n            <li><strong>Femmes plus âgées :</strong> <span>incidence</span> <span>en hausse</span>.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Lecture EDN.</strong> La tranche <span><span class=\"nc-pink nc-bold\">20-29 ans</span></span> est l’âge médian du recours, en cohérence avec l’âge médian du premier rapport et la mise en couple. La <strong>baisse chez les &lt;<span> 20 ans</span></strong> traduit l’amélioration de l’accès à la contraception/contraception d’<span>urgence</span> chez les adolescentes (<span>Norlevo</span> / <span>EllaOne</span> en accès libre, gratuité &lt;<span> 26 ans</span>).\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":0},{"id":"37-5","rang":"A","rubrique":"Définition","titre":"Connaître les conditions de pratique des IVG en France","contenu":"<div class=\"notion-course\"><ul><li>L’IVG est décidée par la femme ; le <span class=\"nc-yellow_bg\">consentement</span> du conjoint n’est pas requis. Information sur les méthodes, risques, alternatives et accompagnement sans jugement.</li><li>Délai légal : jusqu’à la fin de la quatorzième semaine de grossesse, soit seize semaines d’aménorrhée. L’<span class=\"nc-pink nc-bold\">IVG médicamenteuse</span> est possible jusqu’à neuf SA ; la méthode dépend du terme et du choix éclairé.</li><li><span class=\"nc-blue_bg\">Entretien psychosocial</span> proposé aux majeures, obligatoire pour les <span class=\"nc-pink nc-bold\">mineures</span>. Aucun délai minimal de réflexion n’est imposé.</li><li>Une mineure peut demander le secret vis-à-vis des titulaires de l’autorité parentale ; elle est alors accompagnée par une personne majeure de son choix. Son <span class=\"nc-yellow_bg\">consentement</span> personnel demeure indispensable.</li><li>Prise en charge à 100 % selon dispositif français ; accès indépendant de l’accord du partenaire. Respect de la confidentialité et orientation rapide si un professionnel ne pratique pas l’IVG.</li><li>L’information contraceptive peut débuter dès le premier contact et être reprise ensuite ; il n’existe pas d’interdiction de l’aborder avant la deuxième consultation. La contraception reste un choix.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":4},{"id":"37-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les structures de prise en charge des IVG","contenu":"<div class=\"notion-course\"><ul><li>IVG médicamenteuse : établissement de santé, professionnel conventionné en ville ou structure habilitée ; téléconsultation possible dans les conditions prévues.</li><li>IVG instrumentale : établissement de santé ou centre autorisé répondant aux exigences correspondantes. Organiser l’accès en fonction du terme et de l’offre locale.</li><li>Les sages-femmes peuvent réaliser des IVG médicamenteuses et, après formation/conditions réglementaires requises, des IVG instrumentales en établissement de santé. L’ancienne limitation présentée comme un plafond général de douze SA ne doit pas être conservée.</li><li>Un refus de pratiquer doit s’accompagner d’une information et d’une orientation rapide vers une structure pouvant répondre à la demande. Une échéance légale proche impose d’accélérer le parcours.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":0},{"id":"37-7","rang":"A","rubrique":"Prise en charge","titre":"Décrire les étapes de la prise en charge","contenu":"<div class=\"notion-course\"><p>La prise en charge IVG suit un schéma en <span>3 consultations</span> standardisées : 1ère consultation (formulation de la demande) → 2ème consultation (confirmation et réalisation) → consultation de contrôle post-IVG.</p>\n\n      <h4>1ère consultation — Formulation de la demande</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Professionnels</strong></td>\n            <td>Médecin <strong>ou</strong> <span class=\"nc-brown_bg\">sage-femme</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Informations</strong></td>\n            <td>\n              <strong><span class=\"nc-blue_bg\">Entretien psychosocial</span> :</strong> proposé systématiquement, <span>obligatoire pour mineure non émancipée</span>.<br>\n              <strong>Information :</strong> procédures possibles, choix de recours à l’<span class=\"nc-green_bg\">anesthésie locale</span> ou <span class=\"nc-green_bg\">générale</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Documents</strong></td>\n            <td><span class=\"nc-yellow_bg\">Dossier-guide</span> ; <span class=\"nc-yellow_bg\">attestation de 1ère consultation</span> — <strong>remis à la patiente</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Prescriptions</strong></td>\n            <td>\n              <strong>Groupe sanguin :</strong> ABO, Rh.<br>\n              <strong><span class=\"nc-blue_bg\">RAI</span>.</strong><br>\n              <strong><span>Échographie</span> de datation :</strong> <span>non indispensable</span>, mais nécessaire si doute sur le terme ou la localisation.<br>\n              <strong><span>PCR</span> :</strong> <span>Chlamydia trachomatis + gonocoque</span> sur prélèvement vaginal — <span>recommandé avant toute IVG</span>.<br>\n              <strong>FCV :</strong> peut être proposé.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2ème consultation — Confirmation et réalisation de l’IVG</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Déroulement</strong></td>\n            <td>\n              <strong>Vérification de la datation :</strong> IVG autorisée si <span>LCC <span class=\"nc-pink nc-bold\">≤ 90 mm</span></span> et/ou <span>BIP ≤ 30 mm</span>.<br>\n              <strong><span class=\"nc-blue_bg\">Recueil du consentement</span> <span class=\"nc-blue_bg nc-bold\">écrit</span></strong> <span class=\"nc-blue_bg\">de la demande d’IVG</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Réalisation IVG</strong></td>\n            <td>\n              <strong><span class=\"nc-pink nc-bold\">Médicamenteuse</span> :</strong> prise de <span>mifépristone</span> <span class=\"nc-pink nc-bold\">au terme de la consultation</span> + remise du <span>misoprostol</span> pour prise au domicile.<br>\n              <strong>Chirurgicale :</strong> <span class=\"nc-blue_bg\">préparation cervicale</span> ± consultation d’anesthésie si AG prévue → <span class=\"nc-pink_bg\">IVG réalisée </span><span><span class=\"nc-pink_bg\">36-48 h plus tard</span></span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Contraception post-IVG</strong> ⭐</td>\n            <td>\n              Information et choix de la méthode contraceptive <span>se fait <span class=\"nc-green nc-bold\">lors de la 2ème</span> consultation</span> (pas la 1ère).<br>\n              <strong><span class=\"nc-red_bg\">Anneau vaginal</span> :</strong> possible <span><span class=\"nc-red nc-bold\">5 jours après</span></span><span class=\"nc-red nc-bold\"> IVG</span>.<br>\n              <strong><span class=\"nc-red_bg\">DIU</span> :</strong> possible <span><span class=\"nc-pink nc-bold\">10 jours après</span></span> IVG <span class=\"nc-pink nc-bold\">médicamenteuse</span> (après vérification de la vacuité utérine).<br>\n              Autres méthodes : possibles le jour même de l’IVG.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prescriptions</strong></td>\n            <td>\n              <span>Ig anti-D</span> dans les <span>&lt; 72 h</span> pour toute IVG <strong><span class=\"nc-pink_bg nc-bold\">si femme Rh-</span></strong> ;<br>\n              <span><span class=\"nc-pink_bg\">Antalgiques</span></span> (<span>AINS</span> ++) ;<br>\n              <span class=\"nc-pink_bg\">Contraception</span> choisie.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Consultation de contrôle post-IVG</h4>\n\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Quand ?</strong></td>\n            <td><span>J14 - J21</span> après l’IVG.</td>\n          </tr>\n          <tr>\n            <td><strong>Obligatoire ?</strong></td>\n            <td>\n              <strong>Obligatoire</strong> selon gynécologie médicale Medline ;<br>\n              <strong>Conseillée mais non obligatoire</strong> selon gynéco-obstétrique Masson.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Objectifs</strong></td>\n            <td>\n              <strong>Vérifier la réussite de l’IVG médicamenteuse :</strong> <span class=\"nc-blue_bg\">contrôle </span><span><span class=\"nc-blue_bg\">β-hCG</span></span> ou <span class=\"nc-brown_bg\">contrôle </span><span><span class=\"nc-brown_bg\">échographique</span></span> de vacuité utérine.<br>\n              Faire le point sur la contraception prescrite ;<br>\n              Rechercher des complications.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>PIÈGE QCM ⭐.</strong> L’information sur la <span><span class=\"nc-pink_bg\">contraception</span> ne se fait pas à la 1ère consultation</span> mais à la 2ème — le piège classique aux QCM. L’<span>échographie de datation</span> n’est <span>pas indispensable</span> à la 1ère consultation (seulement si doute sur terme/localisation).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 162 — IST</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":2},{"id":"37-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les techniques d’IVG médicamenteuse et chirurgicale","contenu":"<div class=\"notion-course\"><p>Deux techniques distinctes — choix selon l’<span>âge gestationnel</span>, le choix de la patiente et les <span>contre-indications</span>. Les différences en termes de succès, EI et lésions d’organes sont <strong>très faibles</strong> : la femme doit pouvoir choisir la méthode quand c’est possible.</p>\n\n      <h4>IVG médicamenteuse — Médicaments</h4>\n\n      <table>\n        <thead>\n          <tr><th></th><th><span>Mifépristone</span></th><th><span>Misoprostol</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Quand ?</strong></td>\n            <td><em>Administrée <span class=\"nc-pink nc-bold\">au terme de la consultation</span></em></td>\n            <td><em>Administré <span>24-48 h après</span> la mifépristone</em></td>\n          </tr>\n          <tr>\n            <td><strong>Voie</strong></td>\n            <td>PO</td>\n            <td>Transmuqueuse PO ou sublinguale</td>\n          </tr>\n          <tr>\n            <td><strong>Classe</strong></td>\n            <td>\n              <span>Stéroïde de synthèse</span> à fortes propriétés <strong>antiprogestérones</strong> (affinité pour les récepteurs de la progestérone <span>5× supérieure</span> à celle de la progestérone elle-même).\n            </td>\n            <td>\n              <span>Analogue de la prostaglandine PGE1</span>.<br>\n              <em>(Les prostaglandines servent à provoquer des contractions ; les <span>AINS</span> inhibent leur synthèse et étaient utilisés autrefois comme tocolytiques.)</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mode d’action</strong></td>\n            <td>\n              La progestérone est indispensable au développement et au maintien initial de la <span>grossesse</span> (rôle du corps jaune) :\n              <ul>\n                <li><span><span class=\"nc-yellow_bg nc-bold\">Nécrose déciduale</span></span> <span class=\"nc-yellow_bg\">provoquant un</span> <span><span class=\"nc-yellow_bg nc-bold\">détachement de l’œuf</span></span>.</li>\n                <li><span class=\"nc-pink_bg\">Stimule la sécrétion des </span><strong><span class=\"nc-pink_bg\">prostaglandines endogènes</span></strong> → <strong><span class=\"nc-green nc-bold\">contractions utérines</span></strong> + <strong><span class=\"nc-green nc-bold\">ouvre et ramollit le col</span></strong>.</li>\n              </ul>\n            </td>\n            <td>\n              Stimule la contractilité utérine par liaison aux récepteurs spécifiques dans le myomètre ; entraîne l’expulsion de l’œuf grâce à :\n              <ul>\n                <li><strong><span class=\"nc-green_bg\">Relâchement du col utérin</span>.</strong></li>\n                <li><strong>Contractions des fibres musculaires lisses du myomètre.</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>IVG médicamenteuse — Déroulement</h4>\n\n      <ul>\n        <li><strong>Protocole :</strong>\n          <ol>\n            <li><span>Mifépristone</span> PO <strong><span class=\"nc-pink nc-bold\">au terme de la consultation</span></strong>.</li>\n            <li><span>Misoprostol</span> par voie transmuqueuse PO ou sublinguale <strong><span class=\"nc-pink nc-bold\">après </span><span><span class=\"nc-pink nc-bold\">24-48 h</span></span></strong>.</li>\n          </ol>\n        </li>\n        <li><strong>Saignements (expulsion du fœtus) :</strong>\n          <ul>\n            <li>Après mifépristone : saignement possible.</li>\n            <li>Après misoprostol (expulsion) : <span><span class=\"nc-pink nc-bold\">2-4 h après</span></span> dans <span>60 %</span> des cas, ou <span>24-72 h</span> dans <span>40 %</span> des cas.</li>\n            <li><strong>Saignement très abondant ne doit pas excéder <span>2-4 h</span>.</strong></li>\n            <li>Durée moyenne du saignement : <span><span class=\"nc-pink nc-bold\">10-13 jours</span></span>, <span class=\"nc-pink nc-bold\">peut durer jusqu’aux règles suivantes</span>.</li>\n          </ul>\n        </li>\n        <li><strong>Douleurs (contractions utérines) :</strong>\n          <ul>\n            <li>Maximales <span>1-3 h après la prise de misoprostol</span>.</li>\n            <li>Décroissent puis disparaissent peu après l’expulsion complète.</li>\n            <li>CAT : <span><span class=\"nc-pink_bg\">ibuprofène</span></span> ou <span>paracétamol + codéine</span> — <span>pas de paracétamol seul</span>.</li>\n          </ul>\n        </li>\n        <li><strong>Contrôle du succès :</strong>\n          <ul>\n            <li>Soit <span>contrôle échographique</span>.</li>\n            <li>Soit <span>β-<span class=\"nc-blue_bg\">hCG plasmatique ou urinaire</span></span> : succès si <span>baisse &gt; 80 % à J15</span> par rapport au dosage initial.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>IVG chirurgicale (instrumentale) — Déroulement</h4>\n\n      <ul>\n        <li><strong>Rappels :</strong>\n          <ul>\n            <li>Autorisée jusqu’à <span><span class=\"nc-pink_bg\">16 SA</span></span> (<span><span class=\"nc-pink nc-bold\">14 semaines</span></span> de <span>grossesse</span>).</li>\n            <li>Uniquement en établissement de santé public ou privé agréé.</li>\n            <li><span class=\"nc-brown_bg\">Sage-femme</span> habilitée jusqu’à <span>≤ 12 SA</span> depuis 2022.</li>\n          </ul>\n        </li>\n        <li><strong>Préparation cervicale :</strong> <span>systématiquement recommandée</span> avant dilatation :\n          <ul>\n            <li><strong>Objectif :</strong> <span class=\"nc-green nc-bold\">réduire le temps opératoire et les complications rares</span>.</li>\n            <li><strong>Comment ?</strong> <span><span class=\"nc-pink_bg\">Mifépristone</span></span><span class=\"nc-pink_bg\"> ou </span><span><span class=\"nc-pink_bg\">misoprostol</span></span> délivré <span>36-48 h avant</span> l’intervention.</li>\n          </ul>\n        </li>\n        <li><strong>Orientation :</strong> <span>ambulatoire</span> (pas d’<span>hospitalisation</span>, mais établissement de santé).</li>\n        <li><strong>Anesthésie :</strong>\n          <ul>\n            <li><span><span class=\"nc-green_bg\">Anesthésie générale</span></span> (consultation préalable requise).</li>\n            <li><span><span class=\"nc-green_bg\">Anesthésie locale</span></span> <span class=\"nc-green_bg\">paracervicale</span> ou <span class=\"nc-green_bg\">intracervicale</span>.</li>\n          </ul>\n        </li>\n        <li><strong>Évacuation (3 temps) :</strong>\n          <ol>\n            <li>Installation en position gynécologique.</li>\n            <li><strong><span class=\"nc-pink_bg nc-bold\">Dilatation</span> <span class=\"nc-pink_bg nc-bold\">cervicale</span></strong> <span class=\"nc-pink_bg\">à l’aide de</span> <strong><span class=\"nc-pink_bg nc-bold\">bougies</span> <span class=\"nc-pink_bg\">de calibre croissant</span></strong>.</li>\n            <li><strong><span class=\"nc-pink_bg nc-bold\">Aspiration</span></strong> <span class=\"nc-pink_bg\">à l’aide d’une</span> <strong><span class=\"nc-pink_bg nc-bold\">canule</span></strong> <span class=\"nc-pink_bg\">pour évacuer le contenu utérin</span>.</li>\n          </ol>\n        </li>\n        <li><strong><span class=\"nc-brown_bg\">Contrôle échographique</span> :</strong> <span class=\"nc-brown_bg\">non systématique</span>, <span class=\"nc-brown_bg\">possible en per-opératoire pour vérifier la vacuité utérine</span>.</li>\n        <li><strong>CAT si échec/rétention :</strong> <span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pour confirmer le diagnostic</span> → <span><span class=\"nc-pink_bg\">aspiration</span></span> ou <span><span class=\"nc-pink_bg\">exérèse sous contrôle hystéroscopique</span></span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Choix de la méthode.</strong> Les différences entre les 2 méthodes en termes de succès, EI et lésions d’organes sont <strong>très faibles</strong>. Dans tous les cas où c’est possible, la femme doit pouvoir choisir la méthode (médicale ou <span class=\"nc-purple nc-bold\">instrumentale</span>, <span class=\"nc-green_bg\">anesthésie générale</span> ou <span class=\"nc-green_bg\">locale</span>), quel que soit l’âge gestationnel, après exposé des avantages et inconvénients de chacune.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span>surveillance</span> des médicaments - hors anti-<span>infectieux</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":2},{"id":"37-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les contre-indications des différentes méthodes","contenu":"<div class=\"notion-course\"><p>Les <span>contre-indications</span> diffèrent selon la méthode (médicamenteuse <span>vs</span> chirurgicale) et selon le médicament utilisé. Connaître par cœur les <strong>non-CI piégeuses</strong> de l’<span class=\"nc-pink nc-bold\">IVG médicamenteuse</span>.</p>\n\n      <h4>CI spécifiques des médicaments</h4>\n\n      <table>\n        <thead>\n          <tr><th></th><th><span>Mifépristone</span></th><th><span>Misoprostol</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Contre-indications</span></strong></td>\n            <td>\n              <span>Allergie connue</span> à la mifépristone ;<br>\n              <span><span class=\"nc-orange_bg\">Porphyrie héréditaire</span></span> ;<br>\n              <span><span class=\"nc-blue_bg\">Insuffisance surrénalienne chronique</span></span> ;<br>\n              <span><span class=\"nc-blue_bg\">Traitement corticostéroïde chronique</span></span> ;<br>\n              <span><span class=\"nc-red_bg\">Asthme sévère non équilibré</span></span><span class=\"nc-red_bg\"> par un traitement</span>.\n            </td>\n            <td>\n              <span>Allergie</span> au misoprostol ;<br>\n              <span>Allergie</span> aux prostaglandines ;<br>\n              <span><span class=\"nc-red_bg\">Insuffisance rénale</span></span> ;<br>\n              <span><span class=\"nc-red_bg\">Insuffisance hépatique</span></span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Situations à risque (non CI, prudence)</strong></td>\n            <td>\n              <span><span class=\"nc-red_bg\">Insuffisance rénale</span></span> ;<br>\n              <span><span class=\"nc-red_bg\">Insuffisance hépatique</span></span> ;<br>\n              <span>Malnutrition</span>.\n            </td>\n            <td>\n              <span>ATCD cardiovasculaires</span> — précautions d’emploi.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>CI globales de l’IVG médicamenteuse</h4>\n\n      <ul>\n        <li><span><span class=\"nc-orange_bg\">Anémie profonde</span></span><span class=\"nc-orange_bg\"> </span><span><span class=\"nc-orange_bg\">&lt; 9 g/dL</span></span>, <span><span class=\"nc-orange_bg\">troubles de la coagulation</span></span>, <span>anticoagulants</span> (absence de contrôle de l’hémorragie en cas de complication).</li>\n        <li><span>Grossesse ectopique confirmée ou suspectée</span> :\n          <ul>\n            <li>La <span>mifépristone est inefficace sur la GEU</span> par <span><span class=\"nc-red nc-bold\">absence de récepteurs de la progestérone au niveau des trompes</span></span>.</li>\n            <li>IVG médicamenteuse possible devant une <span>grossesse</span> de <strong>localisation inconnue</strong> si : <span class=\"nc-green_bg\">absence de FR de GEU</span> + <span class=\"nc-green_bg\">absence de symptômes de GEU</span> + <span><span class=\"nc-green_bg\">hCG &lt; 1500 UI</span></span>.</li>\n          </ul>\n        </li>\n        <li><span>DIU en place</span> :\n          <ul>\n            <li><strong>Masson :</strong> retrait préférable, mais ne CI pas l’IVG si retrait impossible.</li>\n            <li><strong>Medline :</strong> IVG médicamenteuse <strong>CI si le retrait du DIU est impossible</strong>.</li>\n          </ul>\n        </li>\n        <li><span>CI organisationnelles</span> : patiente isolée, impossibilité de <span>suivi</span>, ne comprenant pas les informations délivrées.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>PIÈGE QCM — ne sont PAS des CI de l’IVG médicamenteuse.</strong>\n        <ul>\n          <li><span><span class=\"nc-red nc-bold\">Allaitement</span></span></li>\n          <li><span>Tabac</span></li>\n          <li><span><span class=\"nc-red nc-bold\">Obésité</span></span></li>\n          <li><span><span class=\"nc-red nc-bold\">Grossesse gémellaire</span></span></li>\n          <li><span><span class=\"nc-red nc-bold\">Utérus cicatriciel</span></span></li>\n        </ul>\n        À connaître par cœur — ce sont les pièges classiques aux QCM.\n      </div>\n\n      <h4>IVG chirurgicale</h4>\n\n      <p>Peu de <span>CI absolues</span> spécifiques. Essentiellement : <span>CI anesthésiques classiques</span> si AG prévue (à évaluer en consultation pré-anesthésique), <span>infection génitale active</span> à traiter au préalable.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span>Grossesse</span> extra-utérine · 245 — Insuffisance surrénale · 330 — Prescription et <span>surveillance</span> des médicaments - hors anti-<span>infectieux</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":0},{"id":"37-10","rang":"B","rubrique":"Suivi et pronostic","titre":"Connaître les principales complications des IVG chirurgicales et médicamenteuses","contenu":"<div class=\"notion-course\"><p>Complications classées en <span>immédiates</span>, <span>secondaires</span> et <span>à long terme</span>. À connaître : profils différents entre <span class=\"nc-pink nc-bold\">IVG médicamenteuse</span> (saignement, douleur) et chirurgicale (hémorragie, mécaniques).</p>\n\n      <h4>Tableau comparatif IVG <span class=\"nc-purple nc-bold\">instrumentale</span> <span>vs</span> <span class=\"nc-pink nc-bold\">médicamenteuse</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Critère</th><th>IVG <span class=\"nc-purple nc-bold\">instrumentale</span></th><th>IVG médicamenteuse</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Acteur</strong></td>\n            <td><span class=\"nc-yellow_bg\">Médecin</span> ; <span class=\"nc-brown_bg\">sage-femme</span> jusqu’à <span>≤ 12</span> SA (2022)</td>\n            <td>Femme (PEC par <span class=\"nc-yellow_bg\">médecin</span> ou <span class=\"nc-brown_bg\">sage-femme</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Invasif ?</strong></td>\n            <td>Oui</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Anesthésie</strong></td>\n            <td><span class=\"nc-green_bg\">Locale</span> ou <span class=\"nc-green_bg\">générale</span> (accidents d’anesthésie = complications spécifiques)</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Durée d’évacuation</strong></td>\n            <td>Quelques <span><span class=\"nc-pink nc-bold\">minutes</span></span></td>\n            <td>Quelques <span><span class=\"nc-pink nc-bold\">heures</span> à <span class=\"nc-pink nc-bold\">jours</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Suivi</span></strong></td>\n            <td>Non indispensable</td>\n            <td><span class=\"nc-yellow_bg\">Nécessaire</span> (entre <span>J14 - J21</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Succès</strong></td>\n            <td><span>99 %</span></td>\n            <td><span>95-98 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Douleurs</strong></td>\n            <td>\n              Peu (anesthésie).<br>\n              <span><span class=\"nc-pink nc-bold\">Ibuprofène</span></span> per (<span>600 mg</span>) et post-opératoire ⭐.\n            </td>\n            <td>\n              <span class=\"nc-green nc-bold\">Absentes</span> à <span class=\"nc-red nc-bold\">sévères</span>.<br>\n              <span><span class=\"nc-pink nc-bold\">Ibuprofène</span></span> en <span>1ère intention</span> ⭐.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Saignement</strong></td>\n            <td>Faibles (<span>3-8 jours</span>)</td>\n            <td><span>10-15 jours</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie</strong></td>\n            <td><span>0,5 %</span></td>\n            <td><span>5 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Complications mécaniques</strong></td>\n            <td>\n              <strong><span class=\"nc-orange_bg\">Déchirure cervicale</span> :</strong> <span>0,2 - 1 %</span> ;<br>\n              <strong>Perforation utérine :</strong> <span>1-4 pour 1000</span>.\n            </td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Échec complet</strong></td>\n            <td><span class=\"nc-green_bg\">Exceptionnel (</span><span><span class=\"nc-green_bg\">1-5 / 1000</span></span><span class=\"nc-green_bg\">)</span> — si impossibilité de dilater le col, ou <span class=\"nc-pink nc-bold\">aspiration</span> en dehors de la cavité utérine</td>\n            <td>Taux de <span>grossesse</span> évolutive (échec total) <span>1 %</span> ; échec partiel plus fréquent</td>\n          </tr>\n          <tr>\n            <td><strong>Infection génitale haute (IGH)</strong></td>\n            <td><span>1 %</span></td>\n            <td><span>0,3 %</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Complications immédiates</h4>\n\n      <ul>\n        <li><strong>Douleur :</strong>\n          <ul>\n            <li>Après misoprostol : <span><span class=\"nc-pink_bg\">ibuprofène</span></span> ou <span class=\"nc-pink_bg\">association </span><span><span class=\"nc-pink_bg\">paracétamol + codéine</span></span> (<span>pas de paracétamol seul</span>).</li>\n            <li>Per/post-opératoire IVG chirurgicale : <span>AINS</span> pouvant être débutés en pré-opératoire.</li>\n          </ul>\n        </li>\n        <li><strong>Hémorragie :</strong>\n          <ul>\n            <li>Risque : <span>0,5 %</span> après IVG <span class=\"nc-purple nc-bold\">instrumentale</span> ; <span>5 %</span> après IVG <span class=\"nc-pink nc-bold\">médicamenteuse</span>.</li>\n            <li>Différentes présentations :\n              <ul>\n                <li><strong><span class=\"nc-blue_bg\">Hémorragie extériorisée</span></strong><span class=\"nc-blue_bg\"> par lésions cervicales</span> (traction du col lors de l’IVG chirurgicale).</li>\n                <li><strong><span class=\"nc-blue_bg\">Hémorragie extériorisée</span></strong><span class=\"nc-blue_bg\"> par atonie utérine</span> (surtout si temps opératoire prolongé, <span>grossesse</span> évoluée).</li>\n                <li><span><span class=\"nc-blue_bg\">Hémopéritoine</span></span><span class=\"nc-blue_bg\"> lors d’une perforation utérine</span>.</li>\n                <li><strong><span class=\"nc-blue_bg\">Hémorragies secondaires</span></strong><span class=\"nc-blue_bg\"> dans le </span><span><span class=\"nc-blue_bg\">&lt; 1 mois</span></span> : IGH, rétention ovulaire, hématométrie résiduelle.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n        <li><strong>Mécaniques</strong> (uniquement IVG chirurgicale, absentes si médicamenteuse) :\n          <ul>\n            <li><span><span class=\"nc-red_bg\">Déchirures cervicales</span></span> (<span>0,2 - 1 %</span>).</li>\n            <li><span>Perforation utérine</span> (<span>1-4 / 1000</span>).</li>\n          </ul>\n        </li>\n        <li><strong>Infectieuses (IGH post-IVG) :</strong>\n          <ul>\n            <li>Risque : <span>1 %</span> après IVG <span class=\"nc-purple nc-bold\">instrumentale</span> ; <span>0,3 %</span> après IVG <span class=\"nc-pink nc-bold\">médicamenteuse</span>.</li>\n            <li>Cause : <span>vaginose bactérienne</span> ou portage asymptomatique de <span>gonocoque</span> / <span>Chlamydia trachomatis</span>.</li>\n            <li>Mesures préventives :\n              <ul>\n                <li><span>Pas d’antibioprophylaxie</span> recommandée quelle que soit la technique <em>(LISA indique qu’elle est recommandée si chir)</em>.</li>\n                <li><span>Dépistage</span> par <span>PCR gonocoque + Chlamydia trachomatis</span> sur prélèvement vaginal (IVG réalisable sans attendre le résultat, mais conseillé).</li>\n                <li>ATB justifiée si prélèvement positif.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n        <li><strong>Décès :</strong> risque du même ordre que la fausse couche spontanée — <span>0,7 / 100 000</span>.</li>\n      </ul>\n\n      <h4>Complications secondaires</h4>\n\n      <ul>\n        <li><span><span class=\"nc-orange_bg\">Pseudo-anévrysmes</span></span> : résultat d’un défect pariétal artériel.</li>\n        <li><span>Malformations artério-veineuses utérines (MAVU)</span> :\n          <ol>\n            <li><strong><span class=\"nc-red nc-bold\">Persistance de tissu ovulaire</span></strong><span class=\"nc-red nc-bold\"> après une IVG</span> <span class=\"nc-pink nc-bold\">médicamenteuse</span> ou <span class=\"nc-purple nc-bold\">instrumentale</span>.</li>\n            <li><strong><span class=\"nc-red nc-bold\">Favorise le défaut de résorption</span></strong><span class=\"nc-red nc-bold\"> de la vascularisation péritrophoblastique</span> → création d’une MAVU.</li>\n          </ol>\n        </li>\n        <li><strong>Traitement des 2 entités :</strong> <span><span class=\"nc-pink nc-bold\">embolisation par radiologie interventionnelle</span></span>.</li>\n      </ul>\n\n      <h4>Complications à long terme</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Pas d’augmentation</strong> du risque de (après 1 ou plusieurs IVG) :\n        <ul>\n          <li>Infertilité.</li>\n          <li>Fausse couche spontanée (<strong>sauf</strong> si intervalle entre l’IVG et la <span>grossesse</span> suivante <span>&lt; 3 mois</span>).</li>\n          <li><span>Grossesse</span> extra-utérine.</li>\n          <li>Anomalies de la placentation.</li>\n          <li>Accouchement prématuré.</li>\n          <li>Cancer du sein.</li>\n          <li>Troubles psychiatriques.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 43 — Hémorragie génitale chez la femme · 162 — IST</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":2},{"id":"37-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les déterminants du choix contraceptif après IVG","contenu":"<div class=\"notion-course\"><ul><li>Discuter la <span class=\"nc-pink_bg\">contraception</span> dès le parcours d’IVG, selon le souhait de la femme : efficacité, acceptabilité, contre-indications et projet de grossesse. Aucune méthode ne doit être imposée.</li><li>La fertilité peut reprendre rapidement. Une contraception hormonale peut généralement être débutée immédiatement selon la méthode d’IVG et le protocole choisi.</li><li><span class=\"nc-red_bg\">DIU</span> possible immédiatement après une <span class=\"nc-pink nc-bold\">aspiration</span> sans complication infectieuse ; après IVG <span class=\"nc-pink nc-bold\">médicamenteuse</span>, poser une fois l’expulsion et l’absence de grossesse évolutive confirmées, selon organisation de l’équipe.</li><li>Expliquer les préservatifs/IST, les oublis et la contraception d’urgence. Prévoir le contrôle de l’efficacité de l’IVG et l’accès à une réévaluation en cas de saignement important, fièvre ou douleur inhabituelle.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":0},{"id":"37-12","rang":"B","rubrique":"Suivi et pronostic","titre":"Identifier les facteurs de risques de récidive","contenu":"<div class=\"notion-course\"><div class=\"callout callout-info\">\n        <strong>Niveau d’exigence.</strong> Le descriptif officiel CNGOF de cet objectif est <strong>volontairement minimal</strong> : ni la fiche EDN ni le Collège de Gynécologie-Obstétrique ne détaillent de liste de FDR de récidive. Les FDR attendus découlent directement des <strong>causes de grossesses non désirées</strong> (cf. obj-1) — essentiellement une <span>contraception absente, mal adaptée ou interrompue</span>.\n      </div>\n\n      <h4>FDR de récidive (dérivés des causes officielles, cf. obj-1)</h4>\n\n      <ul>\n        <li><strong>Échec / oubli / défaut d’utilisation de la contraception</strong> : <span>&gt; 60 %</span> des IVG surviennent chez des femmes <strong>sous contraception</strong> au moment de la <span>grossesse</span> — c’est le FDR majeur.</li>\n        <li><strong>Méthode contraceptive peu efficace</strong> : méthodes naturelles (Ogino, Billings, MAMA), retrait, préservatif seul → privilégier les <span>LARC (DIU, <span class=\"nc-pink nc-bold\">implant</span>)</span> en post-IVG ⭐.</li>\n        <li><strong><span>Vulnérabilité sociale</span></strong> : situations de précarité, isolement, jeunesse, manque d’éducation/d’information.</li>\n        \n        <li><strong>Non-recours à la consultation contraceptive post-IVG</strong> : manque d’information, perte de vue à <span>J14 - J21</span>.</li>\n        <li><strong>Événements de vie à risque</strong> : <span>post-partum</span>, post-IVG, ménopause débutante, changement de partenaire.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Cohérence avec obj-10.</strong> La <strong>prévention de la récidive</strong> repose sur la prescription d’une <span>contraception efficace, longue durée d’action (LARC) si possible</span>, dès la 2ème consultation IVG, avec un <strong><span>suivi</span> rapproché</strong> (consultation de contrôle J14-<span>J21</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Interruption volontaire de grossesse</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Délais légaux <span class=\"kw-etio\">médicamenteux</span></strong></p><ul><li><span class=\"kw-ttt\">IVG médicamenteuse</span> : possible jusqu'à <span class=\"kw-chiffre\">7 semaines de grossesse</span> (<span class=\"kw-chiffre\">9 SA</span>)</li><li>En ville jusqu'à <span class=\"kw-chiffre\">9 SA</span> ; au-delà, <span class=\"kw-ci\">uniquement en établissement</span></li></ul><p><strong>Délais légaux chirurgicaux</strong></p><ul><li><span class=\"kw-ttt\">IVG chirurgicale</span> : possible jusqu'à <span class=\"kw-chiffre\">14 semaines de grossesse</span> (<span class=\"kw-chiffre\">16 SA</span>)</li><li><span class=\"kw-ci\">Impossible en ville</span> — établissement agréé (public ou privé) <strong>obligatoire</strong></li></ul><p><strong>Délai d'accès garanti</strong></p><ul><li>Toute patiente appelant un établissement doit obtenir un <span class=\"kw-chiffre\">RDV de consultation dans les 5 jours</span> suivant son appel</li><li>IVG peut se décider <strong>sans délai de réflexion</strong> (suppression du délai de <span class=\"kw-chiffre\">2 jours</span> depuis 2022)</li></ul><p><strong>Immunoglobulines anti-D</strong></p><p>Prescrire systématiquement : <span class=\"kw-bio\">groupe sanguin + Rh + RAI</span> dès la 1ère consultation</p><ul><li>Injection d'<span class=\"kw-ttt\">Ig anti-D</span> dans les <span class=\"kw-chiffre\">&lt; 72h</span> pour toute IVG si femme <span class=\"kw-etio\">Rh négative</span></li></ul>","hospit":"<p><strong>IVG médicamenteuse en ville <span class=\"q\">— jusqu'à 9 SA</span></strong></p><ul><li>Médecin/SF <strong>conventionné</strong> à un établissement de santé agréé</li><li>Doit être qualifié en <span class=\"kw-def\">gynécologie médicale ou obstétrique</span>, ou justifier d'une pratique suffisante et régulière</li><li><span class=\"kw-ttt\">Mifépristone</span> disponible en pharmacie d'officine (délivrance réservée aux praticiens autorisés)</li></ul><p><strong>IVG en établissement de santé <span class=\"q\">— obligatoire pour la chirurgicale</span></strong></p><ul><li>Établissements publics <span class=\"kw-ci\">ne peuvent pas refuser</span> de pratiquer des IVG</li><li>IVG réalisées en <span class=\"kw-def\">hôpital de jour</span> (séjour <span class=\"kw-chiffre\">&lt; 12h</span>)</li><li>Lits en gynécologie-obstétrique ou <span class=\"kw-ttt\">chirurgie</span> disponibles en cas de complication</li><li><span class=\"kw-def\">Anonymat</span> garanti sur les relevés de sécurité sociale pour les femmes majeures et mineures à l'hôpital</li></ul><p><strong>Clause de conscience</strong></p><ul><li>Médecin/SF n'est pas tenu de pratiquer une IVG</li><li><strong>Obligation</strong> de communiquer immédiatement le nom et les coordonnées d'autres praticiens si refus</li></ul>","principes":"<p>Démarche en <strong>2 consultations</strong> : 1ère consultation (formulation de la demande) + 2ème consultation (confirmation + réalisation). Bilan initial systématique : <span class=\"kw-bio\">groupe sanguin ABO + Rh + RAI</span> · <span class=\"kw-bio\">PCR Chlamydia trachomatis + gonocoque</span> sur prélèvement vaginal. Consentement <strong>écrit</strong> de la femme (pas du conjoint). <span class=\"kw-ci\">GEU confirmée ou suspectée = contre-indication à l'IVG médicamenteuse</span> (absence de récepteurs à la progestérone dans les trompes).</p><p><strong>IVG médicamenteuse — protocole</strong></p><ul><li><strong><span class=\"kw-chiffre\">J0</span> :</strong> <span class=\"kw-ttt\">mifépristone</span> per os (anti-progestérone) au terme de la 2ème consultation</li><li><strong><span class=\"kw-chiffre\">J1</span>-J2 :</strong> <span class=\"kw-ttt\">misoprostol</span> (analogue PGE1) par voie transmuqueuse orale ou sublinguale, <span class=\"kw-chiffre\">24-48h</span> après la mifépristone</li><li>Expulsion survient le plus souvent <span class=\"kw-chiffre\">2-4h</span> après la prise de misoprostol (<span class=\"kw-chiffre\">60 %</span> des cas)</li><li>Taux de succès : <span class=\"kw-chiffre\">95-98 %</span> — taux d'échec global <span class=\"kw-chiffre\">5 %</span> (<span class=\"kw-ci\">grossesse</span> évolutive résiduelle <span class=\"kw-chiffre\">&lt; 1 %</span>)</li></ul><p><strong>IVG chirurgicale — protocole</strong></p><p><span class=\"kw-ci\">IVG chirurgicale impossible en ville</span> : établissement agréé obligatoire</p><ul><li><span class=\"kw-ttt\">Préparation cervicale</span> systématiquement recommandée (<span class=\"kw-ttt\">mifépristone</span> ou <span class=\"kw-ttt\">misoprostol</span> délivré <span class=\"kw-chiffre\">36-48h</span> avant)</li><li>Technique : <strong>dilatation cervicale</strong> (bougies de calibre croissant) puis <strong>aspiration</strong> (canule)</li><li>Anesthésie locale paracervicale ou générale (consultation d'anesthésie si AG prévue)</li><li>Taux de succès : <span class=\"kw-chiffre\">&gt; 99 %</span> ; complications mécaniques rares (<span class=\"kw-etio\">perforation utérine</span> <span class=\"kw-chiffre\">1-4/1000</span>)</li></ul><p><strong><span class=\"kw-ci\">Contre-indications</span> à l'IVG médicamenteuse</strong></p><ul><li><span class=\"kw-ci\">GEU confirmée ou suspectée</span> (mifépristone inefficace sur les trompes)</li><li><span class=\"kw-ci\">Anémie profonde &lt; 9 g/dL</span>, troubles de la coagulation, <span class=\"kw-ttt\">anticoagulants</span></li><li><span class=\"kw-ci\">DIU en place</span> si retrait impossible</li><li><span class=\"kw-ci\">Contre-indications organisationnelles</span> : isolement, impossibilité de <span class=\"kw-def\">suivi</span></li><li>Non-CI : <span class=\"kw-ci\">allaitement</span>, tabac, <span class=\"kw-etio\">obésité</span>, grossesse gémellaire, utérus cicatriciel</li></ul>","suivi":"<p><strong>Consultation de contrôle : </strong> <span class=\"kw-chiffre\">J14-J21</span> après l'IVG — vérification de la vacuité utérine (<span class=\"kw-imagerie\">contrôle échographique</span> ou <span class=\"kw-bio\">β-hCG</span> : succès si baisse <span class=\"kw-chiffre\">&gt; 80 %</span> à <span class=\"kw-chiffre\">J15</span> versus dosage initial) + bilan de la contraception + recherche de complications.</p><p><strong>Contraception post-IVG</strong></p><ul><li>Information et choix de la méthode contraceptive lors de la <strong>2ème consultation</strong> (pas la 1ère)</li><li><span class=\"kw-ttt\">Contraception orale / patch</span> : possible <strong>le jour même de l'IVG</strong></li><li><span class=\"kw-ttt\">Implant</span> : insertion le jour de l'IVG instrumentale ou dès la prise de mifépristone</li><li><span class=\"kw-ttt\">DIU</span> : immédiat après IVG chirurgicale ; <span class=\"kw-chiffre\">10 jours</span> après IVG médicamenteuse (après vérification vacuité)</li><li><span class=\"kw-ttt\">Anneau vaginal</span> : <span class=\"kw-chiffre\">5 jours</span> après IVG instrumentale ou dans la semaine après mifépristone</li></ul><p><strong>Signes d'alerte à surveiller</strong></p><ul><li><span class=\"kw-alerte\">Hémorragie prolongée</span> ou <strong>saignements au-delà du retour de règles</strong> → évoquer rétention ovulaire</li><li>CAT si rétention : <span class=\"kw-imagerie\">échographie</span> confirmatrice puis <span class=\"kw-ttt\">aspiration</span> ou <span class=\"kw-ttt\">exérèse</span> sous contrôle <span class=\"kw-imagerie\">hystéroscopique</span></li><li><span class=\"kw-alerte\">Infection génitale haute (IGH)</span> post-IVG : <span class=\"kw-chiffre\">1 %</span> après chirurgicale, <span class=\"kw-chiffre\">0,3 %</span> après médicamenteuse</li><li><span class=\"kw-def\">Dépistage</span> préventif : <span class=\"kw-bio\">PCR Gonocoque et Chlamydia</span> avant toute IVG (ATB si prélèvement positif)</li></ul>"},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Demande d’interruption de grossesse","detail":"<ul><li>Accueil confidentiel ; repères légaux et épidémiologiques dans le cours.</li></ul>","branches":[{"label":"Douleur, malaise ou saignement important","to":"urgent"},{"label":"Situation stable","to":"terme"}]},{"id":"urgent","kind":"urgent","label":"Évaluer l’urgence et localiser la grossesse","detail":"<ul><li>Exclure GEU et hémorragie ; soins avant parcours programmé.</li></ul>","branches":[]},{"id":"terme","kind":"decision","label":"Dater et orienter sans délai","detail":"<ul><li>Information, consentement, structures accessibles ; cadre spécifique des mineures.</li></ul>","branches":[{"label":"Méthode médicamenteuse éligible","to":"med"},{"label":"Méthode instrumentale choisie/indiquée","to":"instrument"},{"label":"Terme hors cadre ou incertain","to":"avis"}]},{"id":"med","kind":"decision","label":"Mifépristone puis misoprostol","detail":"<ul><li>Jusqu’à 9 SA dans le cadre français ; vérifier contre-indications et organisation du suivi.</li></ul>","branches":[{"label":"Contrôle et consignes","to":"suivi"}]},{"id":"instrument","kind":"decision","label":"Aspiration en structure autorisée","detail":"<ul><li>Jusqu’à 16 SA ; anesthésie et préparation adaptées.</li></ul>","branches":[{"label":"Contrôle et consignes","to":"suivi"}]},{"id":"avis","kind":"uncertain","label":"Avis rapide d’une équipe compétente","detail":"<ul><li>Clarifier le terme et les possibilités ; ne pas confondre IVG et IMG.</li></ul>","branches":[]},{"id":"suivi","kind":"finish","label":"Vérifier l’efficacité et accompagner","detail":"<ul><li>Contrôle, signes d’alarme, contraception choisie et soutien ; retour rapide si complication.</li></ul>","branches":[]}]},"cards":[{"i":"290a08452b7a","n":37,"o":"37-1","u":"Définition","t":"Connaître l’histoire politique et sociale qui a mené à la loi sur l’interruption volontaire de grossesse (IVG) de 1975","q":"Quel était le statut de l'avortement en France avant la loi Veil de 1975, et quelles en étaient les conséquences ?","a":"<div class=\"notion-course\"><p>Avant 1975, l'avortement était un acte <strong>réprimé par la loi</strong> et passible de prison. Cela entraînait un grand nombre d'<strong>avortements clandestins</strong>, responsables de <strong>plus de 250 décès</strong> de femmes par an.</p></div>"},{"i":"5ce4e57a204d","n":37,"o":"37-1","u":"Définition","t":"Connaître l’histoire politique et sociale qui a mené à la loi sur l’interruption volontaire de grossesse (IVG) de 1975","q":"Quelle loi française a autorisé la contraception et en quelle année ?","a":"<div class=\"notion-course\"><p>La <strong>loi Neuwirth</strong> a <span class=\"nc-green_bg\">autorisé la contraception</span> en France en <strong>1967</strong>. Ses décrets d'application n'ont été effectifs qu'à partir de 1974.</p></div>"},{"i":"eb901802ba6b","n":37,"o":"37-1","u":"Définition","t":"Connaître l’histoire politique et sociale qui a mené à la loi sur l’interruption volontaire de grossesse (IVG) de 1975","q":"Quel est l'impact de la loi Veil de 1975 sur l'Interruption Volontaire de Grossesse (IVG) en France ?","a":"<div class=\"notion-course\"><p>La loi Veil du 17 janvier 1975 a <strong>dépénalisé</strong> l'Interruption Volontaire de Grossesse (IVG) en France. Il est important de noter qu'elle ne l'a pas légalisée, mais bien dépénalisée.</p></div>"},{"i":"f93a55ca4e9d","n":37,"o":"37-1","u":"Définition","t":"Connaître l’histoire politique et sociale qui a mené à la loi sur l’interruption volontaire de grossesse (IVG) de 1975","q":"Quelle évolution juridique majeure concernant l'Interruption Volontaire de Grossesse (IVG) est intervenue le 8 mars 2024 en France ?","a":"<div class=\"notion-course\"><p>Le 8 mars 2024, une <strong>loi constitutionnelle</strong> a inscrit la <strong>liberté garantie des femmes de recourir à l'IVG</strong> dans la Constitution de 1958. La France est le premier pays à inscrire cette liberté au niveau constitutionnel.</p></div>"},{"i":"4b49c9af9386","n":37,"o":"37-2","u":"Étiologies","t":"Connaître les causes de grossesses non désirées","q":"L'absence de contraception est-elle la principale explication des grossesses non désirées ?","a":"<div class=\"notion-course\"><p>Non. Il est important de retenir que <strong>plus de 60 %</strong> des femmes réalisant une IVG avaient une couverture contraceptive en début de grossesse. L'<strong>échec ou l'inadaptation de la contraception</strong> prime donc sur l'absence de contraception.</p></div>"},{"i":"bee0c3efd8ae","n":37,"o":"37-2","u":"Étiologies","t":"Connaître les causes de grossesses non désirées","q":"Quelles sont les trois causes officielles (CNGOF) de grossesses non désirées ?","a":"<div class=\"notion-course\"><ul><li><strong>Absence de contraception</strong>.</li><li><strong>Changement de méthode contraceptive</strong> : la période de transition est à risque.</li><li><strong>Méthode non adaptée</strong> : méthode peu efficace ou mal utilisée au regard du mode de vie (ex : oubli de pilule, retard de patch/anneau, retrait, méthodes naturelles).</li></ul></div>"},{"i":"db9d22876673","n":37,"o":"37-2","u":"Étiologies","t":"Connaître les causes de grossesses non désirées","q":"Selon le CNGOF, quelle est la première cause de grossesse non désirée ?","a":"<div class=\"notion-course\"><p>La première cause est l'<strong>échec ou l'inadaptation de la contraception</strong>. Environ <strong>deux tiers</strong> des femmes ayant recours à une IVG utilisaient une méthode contraceptive au moment de la grossesse.</p></div>"},{"i":"82867c5ee8f9","n":37,"o":"37-4","u":"Epidémiologie","t":"Connaître l’âge de la population réalisant le plus d’IVG","q":"Quelle est l'explication principale de la baisse de l'incidence de l'Interruption Volontaire de Grossesse (IVG) chez les adolescentes en France ?","a":"<div class=\"notion-course\"><p>La baisse de l'incidence de l'IVG chez les adolescentes est principalement due à l'<strong>amélioration de l'accès à la contraception</strong> et à la <strong>contraception d'urgence</strong> (par exemple, Norlevo/EllaOne en accès libre et gratuité pour les moins de 26 ans).</p></div>"},{"i":"d4306536bc08","n":37,"o":"37-4","u":"Epidémiologie","t":"Connaître l’âge de la population réalisant le plus d’IVG","q":"Comment a évolué l'incidence de l'Interruption Volontaire de Grossesse (IVG) chez les femmes de 20 à 25 ans et chez les femmes plus âgées en France ?","a":"<div class=\"notion-course\"><ul><li>Chez les femmes de <strong>20-25 ans</strong> : l'incidence est <strong><span class=\"nc-red nc-bold\">stable</span></strong>.</li><li>Chez les <strong>femmes plus âgées</strong> : l'incidence est <strong>en hausse</strong>.</li></ul></div>"},{"i":"feffa8bed0d1","n":37,"o":"37-4","u":"Epidémiologie","t":"Connaître l’âge de la population réalisant le plus d’IVG","q":"Quelle est la tranche d'âge la plus concernée par le recours à l'Interruption Volontaire de Grossesse (IVG) en France ?","a":"<div class=\"notion-course\"><p>La tranche d'âge la plus concernée par le recours à l'IVG en France est <strong><span class=\"nc-pink nc-bold\">20-29 ans</span></strong>.</p></div>"},{"i":"ff9c341d543c","n":37,"o":"37-4","u":"Epidémiologie","t":"Connaître l’âge de la population réalisant le plus d’IVG","q":"Comment a évolué l'incidence de l'Interruption Volontaire de Grossesse (IVG) chez les femmes de moins de 20 ans en France ?","a":"<div class=\"notion-course\"><p>L'incidence de l'IVG chez les femmes de <strong>moins de 20 ans</strong> est <strong>en baisse</strong>.</p></div>"},{"i":"3aa420e9903d","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"À quel moment l'information et l'accès à la contraception sont-ils proposés après une IVG en France ?","a":"<div class=\"notion-course\"><ul><li>L’IVG est décidée par la femme ; le <span class=\"nc-yellow_bg\">consentement</span> du conjoint n’est pas requis. Information sur les méthodes, risques, alternatives et accompagnement sans jugement.</li><li>Délai légal : jusqu’à la fin de la quatorzième semaine de grossesse, soit seize semaines d’aménorrhée. L’<span class=\"nc-pink nc-bold\">IVG médicamenteuse</span> est possible jusqu’à neuf SA ; la méthode dépend du terme et du choix éclairé.</li><li><span class=\"nc-blue_bg\">Entretien psychosocial</span> proposé aux majeures, obligatoire pour les <span class=\"nc-pink nc-bold\">mineures</span>. Aucun délai minimal de réflexion n’est imposé.</li><li>Une mineure peut demander le secret vis-à-vis des titulaires de l’autorité parentale ; elle est alors accompagnée par une personne majeure de son choix. Son <span class=\"nc-yellow_bg\">consentement</span> personnel demeure indispensable.</li><li>Prise en charge à 100 % selon dispositif français ; accès indépendant de l’accord du partenaire. Respect de la confidentialité et orientation rapide si un professionnel ne pratique pas l’IVG.</li><li>L’information contraceptive peut débuter dès le premier contact et être reprise ensuite ; il n’existe pas d’interdiction de l’aborder avant la deuxième consultation. La contraception reste un choix.</li></ul></div>"},{"i":"4691e44b270c","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"Quel est le délai de réflexion légal avant de prendre la décision d'une IVG en France ?","a":"<div class=\"notion-course\"><ul><li>L’IVG est décidée par la femme ; le <span class=\"nc-yellow_bg\">consentement</span> du conjoint n’est pas requis. Information sur les méthodes, risques, alternatives et accompagnement sans jugement.</li><li>Délai légal : jusqu’à la fin de la quatorzième semaine de grossesse, soit seize semaines d’aménorrhée. L’<span class=\"nc-pink nc-bold\">IVG médicamenteuse</span> est possible jusqu’à neuf SA ; la méthode dépend du terme et du choix éclairé.</li><li><span class=\"nc-blue_bg\">Entretien psychosocial</span> proposé aux majeures, obligatoire pour les <span class=\"nc-pink nc-bold\">mineures</span>. Aucun délai minimal de réflexion n’est imposé.</li><li>Une mineure peut demander le secret vis-à-vis des titulaires de l’autorité parentale ; elle est alors accompagnée par une personne majeure de son choix. Son <span class=\"nc-yellow_bg\">consentement</span> personnel demeure indispensable.</li><li>Prise en charge à 100 % selon dispositif français ; accès indépendant de l’accord du partenaire. Respect de la confidentialité et orientation rapide si un professionnel ne pratique pas l’IVG.</li><li>L’information contraceptive peut débuter dès le premier contact et être reprise ensuite ; il n’existe pas d’interdiction de l’aborder avant la deuxième consultation. La contraception reste un choix.</li></ul></div>"},{"i":"740e9ec0c2bf","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"Dans quelles situations l'entretien psychosocial est-il obligatoire avant une IVG en France ?","a":"<div class=\"notion-course\"><ul><li>L’IVG est décidée par la femme ; le <span class=\"nc-yellow_bg\">consentement</span> du conjoint n’est pas requis. Information sur les méthodes, risques, alternatives et accompagnement sans jugement.</li><li>Délai légal : jusqu’à la fin de la quatorzième semaine de grossesse, soit seize semaines d’aménorrhée. L’<span class=\"nc-pink nc-bold\">IVG médicamenteuse</span> est possible jusqu’à neuf SA ; la méthode dépend du terme et du choix éclairé.</li><li><span class=\"nc-blue_bg\">Entretien psychosocial</span> proposé aux majeures, obligatoire pour les <span class=\"nc-pink nc-bold\">mineures</span>. Aucun délai minimal de réflexion n’est imposé.</li><li>Une mineure peut demander le secret vis-à-vis des titulaires de l’autorité parentale ; elle est alors accompagnée par une personne majeure de son choix. Son <span class=\"nc-yellow_bg\">consentement</span> personnel demeure indispensable.</li><li>Prise en charge à 100 % selon dispositif français ; accès indépendant de l’accord du partenaire. Respect de la confidentialité et orientation rapide si un professionnel ne pratique pas l’IVG.</li><li>L’information contraceptive peut débuter dès le premier contact et être reprise ensuite ; il n’existe pas d’interdiction de l’aborder avant la deuxième consultation. La contraception reste un choix.</li></ul></div>"},{"i":"8cbc6e24feb6","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"Quelles sont les spécificités de la prise en charge d'une IVG pour une femme mineure non émancipée en France ?","a":"<div class=\"notion-course\"><ul><li>L’IVG est décidée par la femme ; le <span class=\"nc-yellow_bg\">consentement</span> du conjoint n’est pas requis. Information sur les méthodes, risques, alternatives et accompagnement sans jugement.</li><li>Délai légal : jusqu’à la fin de la quatorzième semaine de grossesse, soit seize semaines d’aménorrhée. L’<span class=\"nc-pink nc-bold\">IVG médicamenteuse</span> est possible jusqu’à neuf SA ; la méthode dépend du terme et du choix éclairé.</li><li><span class=\"nc-blue_bg\">Entretien psychosocial</span> proposé aux majeures, obligatoire pour les <span class=\"nc-pink nc-bold\">mineures</span>. Aucun délai minimal de réflexion n’est imposé.</li><li>Une mineure peut demander le secret vis-à-vis des titulaires de l’autorité parentale ; elle est alors accompagnée par une personne majeure de son choix. Son <span class=\"nc-yellow_bg\">consentement</span> personnel demeure indispensable.</li><li>Prise en charge à 100 % selon dispositif français ; accès indépendant de l’accord du partenaire. Respect de la confidentialité et orientation rapide si un professionnel ne pratique pas l’IVG.</li><li>L’information contraceptive peut débuter dès le premier contact et être reprise ensuite ; il n’existe pas d’interdiction de l’aborder avant la deuxième consultation. La contraception reste un choix.</li></ul></div>"},{"i":"d7d6afad4022","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"Quelles sont les conditions de validité du consentement pour une IVG en France ?","a":"<div class=\"notion-course\"><ul><li>L’IVG est décidée par la femme ; le <span class=\"nc-yellow_bg\">consentement</span> du conjoint n’est pas requis. Information sur les méthodes, risques, alternatives et accompagnement sans jugement.</li><li>Délai légal : jusqu’à la fin de la quatorzième semaine de grossesse, soit seize semaines d’aménorrhée. L’<span class=\"nc-pink nc-bold\">IVG médicamenteuse</span> est possible jusqu’à neuf SA ; la méthode dépend du terme et du choix éclairé.</li><li><span class=\"nc-blue_bg\">Entretien psychosocial</span> proposé aux majeures, obligatoire pour les <span class=\"nc-pink nc-bold\">mineures</span>. Aucun délai minimal de réflexion n’est imposé.</li><li>Une mineure peut demander le secret vis-à-vis des titulaires de l’autorité parentale ; elle est alors accompagnée par une personne majeure de son choix. Son <span class=\"nc-yellow_bg\">consentement</span> personnel demeure indispensable.</li><li>Prise en charge à 100 % selon dispositif français ; accès indépendant de l’accord du partenaire. Respect de la confidentialité et orientation rapide si un professionnel ne pratique pas l’IVG.</li><li>L’information contraceptive peut débuter dès le premier contact et être reprise ensuite ; il n’existe pas d’interdiction de l’aborder avant la deuxième consultation. La contraception reste un choix.</li></ul></div>"},{"i":"e1f3eff3b123","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"Comment une IVG est-elle prise en charge financièrement en France ?","a":"<div class=\"notion-course\"><ul><li>L’IVG est décidée par la femme ; le <span class=\"nc-yellow_bg\">consentement</span> du conjoint n’est pas requis. Information sur les méthodes, risques, alternatives et accompagnement sans jugement.</li><li>Délai légal : jusqu’à la fin de la quatorzième semaine de grossesse, soit seize semaines d’aménorrhée. L’<span class=\"nc-pink nc-bold\">IVG médicamenteuse</span> est possible jusqu’à neuf SA ; la méthode dépend du terme et du choix éclairé.</li><li><span class=\"nc-blue_bg\">Entretien psychosocial</span> proposé aux majeures, obligatoire pour les <span class=\"nc-pink nc-bold\">mineures</span>. Aucun délai minimal de réflexion n’est imposé.</li><li>Une mineure peut demander le secret vis-à-vis des titulaires de l’autorité parentale ; elle est alors accompagnée par une personne majeure de son choix. Son <span class=\"nc-yellow_bg\">consentement</span> personnel demeure indispensable.</li><li>Prise en charge à 100 % selon dispositif français ; accès indépendant de l’accord du partenaire. Respect de la confidentialité et orientation rapide si un professionnel ne pratique pas l’IVG.</li><li>L’information contraceptive peut débuter dès le premier contact et être reprise ensuite ; il n’existe pas d’interdiction de l’aborder avant la deuxième consultation. La contraception reste un choix.</li></ul></div>"},{"i":"116e7e328934","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Quelles sont les obligations des établissements de santé concernant la prise en charge des interruptions volontaires de grossesse (IVG) ?","a":"<div class=\"notion-course\"><ul><li>IVG médicamenteuse : établissement de santé, professionnel conventionné en ville ou structure habilitée ; téléconsultation possible dans les conditions prévues.</li><li>IVG instrumentale : établissement de santé ou centre autorisé répondant aux exigences correspondantes. Organiser l’accès en fonction du terme et de l’offre locale.</li><li>Les sages-femmes peuvent réaliser des IVG médicamenteuses et, après formation/conditions réglementaires requises, des IVG instrumentales en établissement de santé. L’ancienne limitation présentée comme un plafond général de douze SA ne doit pas être conservée.</li><li>Un refus de pratiquer doit s’accompagner d’une information et d’une orientation rapide vers une structure pouvant répondre à la demande. Une échéance légale proche impose d’accélérer le parcours.</li></ul></div>"},{"i":"2db001f0d71e","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Comment la clause de conscience et l'entrave à l'IVG sont-elles régulées par la loi française ?","a":"<div class=\"notion-course\"><ul><li>IVG médicamenteuse : établissement de santé, professionnel conventionné en ville ou structure habilitée ; téléconsultation possible dans les conditions prévues.</li><li>IVG instrumentale : établissement de santé ou centre autorisé répondant aux exigences correspondantes. Organiser l’accès en fonction du terme et de l’offre locale.</li><li>Les sages-femmes peuvent réaliser des IVG médicamenteuses et, après formation/conditions réglementaires requises, des IVG instrumentales en établissement de santé. L’ancienne limitation présentée comme un plafond général de douze SA ne doit pas être conservée.</li><li>Un refus de pratiquer doit s’accompagner d’une information et d’une orientation rapide vers une structure pouvant répondre à la demande. Une échéance légale proche impose d’accélérer le parcours.</li></ul></div>"},{"i":"4bf05b040061","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Quels professionnels de santé sont habilités à réaliser une interruption volontaire de grossesse (IVG) médicamenteuse et chirurgicale, et sous quelles conditions ?","a":"<div class=\"notion-course\"><ul><li>IVG médicamenteuse : établissement de santé, professionnel conventionné en ville ou structure habilitée ; téléconsultation possible dans les conditions prévues.</li><li>IVG instrumentale : établissement de santé ou centre autorisé répondant aux exigences correspondantes. Organiser l’accès en fonction du terme et de l’offre locale.</li><li>Les sages-femmes peuvent réaliser des IVG médicamenteuses et, après formation/conditions réglementaires requises, des IVG instrumentales en établissement de santé. L’ancienne limitation présentée comme un plafond général de douze SA ne doit pas être conservée.</li><li>Un refus de pratiquer doit s’accompagner d’une information et d’une orientation rapide vers une structure pouvant répondre à la demande. Une échéance légale proche impose d’accélérer le parcours.</li></ul></div>"},{"i":"7f0d9deb24ac","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Dans quelles structures une interruption volontaire de grossesse (IVG) médicamenteuse peut-elle être réalisée en ville et quelles sont les conditions d'habilitation des professionnels ?","a":"<div class=\"notion-course\"><ul><li>IVG médicamenteuse : établissement de santé, professionnel conventionné en ville ou structure habilitée ; téléconsultation possible dans les conditions prévues.</li><li>IVG instrumentale : établissement de santé ou centre autorisé répondant aux exigences correspondantes. Organiser l’accès en fonction du terme et de l’offre locale.</li><li>Les sages-femmes peuvent réaliser des IVG médicamenteuses et, après formation/conditions réglementaires requises, des IVG instrumentales en établissement de santé. L’ancienne limitation présentée comme un plafond général de douze SA ne doit pas être conservée.</li><li>Un refus de pratiquer doit s’accompagner d’une information et d’une orientation rapide vers une structure pouvant répondre à la demande. Une échéance légale proche impose d’accélérer le parcours.</li></ul></div>"},{"i":"8c3c0df0c323","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Quels sont les différents délais légaux pour la réalisation d'une interruption volontaire de grossesse (IVG) et les techniques associées ?","a":"<div class=\"notion-course\"><ul><li>IVG médicamenteuse : établissement de santé, professionnel conventionné en ville ou structure habilitée ; téléconsultation possible dans les conditions prévues.</li><li>IVG instrumentale : établissement de santé ou centre autorisé répondant aux exigences correspondantes. Organiser l’accès en fonction du terme et de l’offre locale.</li><li>Les sages-femmes peuvent réaliser des IVG médicamenteuses et, après formation/conditions réglementaires requises, des IVG instrumentales en établissement de santé. L’ancienne limitation présentée comme un plafond général de douze SA ne doit pas être conservée.</li><li>Un refus de pratiquer doit s’accompagner d’une information et d’une orientation rapide vers une structure pouvant répondre à la demande. Une échéance légale proche impose d’accélérer le parcours.</li></ul></div>"},{"i":"f05914ed12d2","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Dans quelles situations l'anonymat est-il garanti pour les interruptions volontaires de grossesse (IVG) en ville et à l'hôpital ?","a":"<div class=\"notion-course\"><ul><li>IVG médicamenteuse : établissement de santé, professionnel conventionné en ville ou structure habilitée ; téléconsultation possible dans les conditions prévues.</li><li>IVG instrumentale : établissement de santé ou centre autorisé répondant aux exigences correspondantes. Organiser l’accès en fonction du terme et de l’offre locale.</li><li>Les sages-femmes peuvent réaliser des IVG médicamenteuses et, après formation/conditions réglementaires requises, des IVG instrumentales en établissement de santé. L’ancienne limitation présentée comme un plafond général de douze SA ne doit pas être conservée.</li><li>Un refus de pratiquer doit s’accompagner d’une information et d’une orientation rapide vers une structure pouvant répondre à la demande. Une échéance légale proche impose d’accélérer le parcours.</li></ul></div>"},{"i":"148468e8b0d3","n":37,"o":"37-7","u":"Prise en charge","t":"Décrire les étapes de la prise en charge","q":"Quels sont les éléments clés de la deuxième consultation d'IVG et les particularités de l'information contraceptive ?","a":"<div class=\"notion-course\"><p>La 2ème consultation d'IVG comprend :</p><ul><li>La <strong>vérification de la datation</strong> (IVG autorisée si LCC <span class=\"nc-pink nc-bold\">≤ 90 mm</span> et/ou BIP ≤ 30 mm).</li><li>Le <span class=\"nc-blue_bg\">recueil du </span><strong><span class=\"nc-blue_bg\">consentement</span> <span class=\"nc-blue_bg nc-bold\">écrit</span></strong>.</li><li>La <strong>réalisation de l'IVG</strong> (médicamenteuse ou chirurgicale).</li><li>L'<strong>information et le choix de la méthode contraceptive post-IVG</strong>, qui se fait lors de cette 2ème consultation (et non la 1ère).</li><li>Les <strong>prescriptions</strong> : Ig anti-D <span class=\"nc-pink_bg nc-bold\">si femme Rh-</span>, <span class=\"nc-pink_bg\">antalgiques</span> (AINS), <span class=\"nc-pink_bg\">contraception</span> choisie.</li></ul></div>"},{"i":"8bb9d6bb7896","n":37,"o":"37-7","u":"Prise en charge","t":"Décrire les étapes de la prise en charge","q":"Quelles sont les trois consultations clés dans la prise en charge de l'interruption volontaire de grossesse (IVG) ?","a":"<div class=\"notion-course\"><p>La prise en charge de l'IVG suit un schéma en <strong>trois consultations standardisées</strong> :</p><ul><li>La <strong>1ère consultation</strong> : formulation de la demande.</li><li>La <strong>2ème consultation</strong> : confirmation et réalisation de l'IVG.</li><li>La <strong>consultation de contrôle post-IVG</strong>.</li></ul></div>"},{"i":"bb9586d9308f","n":37,"o":"37-7","u":"Prise en charge","t":"Décrire les étapes de la prise en charge","q":"Quels sont les éléments clés de la première consultation d'IVG (formulation de la demande) ?","a":"<div class=\"notion-course\"><p>La 1ère consultation permet la formulation <span class=\"nc-blue_bg\">de la demande d'IVG</span> et comprend :</p><ul><li>Des <strong>informations</strong> sur les procédures, le choix de l'anesthésie.</li><li>Un <strong><span class=\"nc-blue_bg\">entretien psychosocial</span></strong> proposé systématiquement, obligatoire pour les mineures non émancipées.</li><li>La remise d'un <strong><span class=\"nc-yellow_bg\">dossier-guide</span></strong> et d'une attestation de la 1ère consultation.</li><li>Des <strong>prescriptions</strong> : groupe sanguin (ABO, Rh, <span class=\"nc-blue_bg\">RAI</span>), échographie de datation si doute, PCR <em>Chlamydia trachomatis</em> et gonocoque (recommandé).</li></ul></div>"},{"i":"dc04dd1e26f0","n":37,"o":"37-7","u":"Prise en charge","t":"Décrire les étapes de la prise en charge","q":"Quand et quels sont les objectifs de la consultation de contrôle post-IVG ?","a":"<div class=\"notion-course\"><p>La consultation de contrôle post-IVG a lieu entre <strong>J14 et J21</strong> après l'IVG. Elle est considérée comme <strong>obligatoire</strong> selon certaines références.</p><p>Ses objectifs sont de :</p><ul><li>Vérifier la <strong>réussite de l'IVG</strong> (<span class=\"nc-blue_bg\">contrôle β-hCG</span> ou échographique de vacuité utérine).</li><li>Faire le point sur la <strong>contraception</strong> prescrite.</li><li>Rechercher d'éventuelles <strong>complications</strong>.</li></ul></div>"},{"i":"e348b3a38285","n":37,"o":"37-3","u":"Epidémiologie","t":"Connaître le nombre d’IVG réalisés en France","q":"Que retenir concernant le nombre d’IVG réalisés en France ?","a":"<div class=\"notion-course\"><p>Chiffres-clés de l’<span>épidémiologie</span> de l’IVG en France (données <span>2019</span>) :</p>\n\n      <ul>\n        <li><strong>Nombre annuel d’IVG en France :</strong> <span>230 000 IVG</span> (en 2019).</li>\n        <li><strong>Tendance :</strong> <span>incidence</span> <span>relativement <span class=\"nc-red nc-bold\">stable</span></span>, avec <strong><span class=\"nc-red nc-bold\">légère augmentation</span></strong> en 2019.</li>\n        <li><strong>Rapport aux naissances :</strong> <span>1 IVG pour 3 naissances</span>.</li>\n        <li><strong>Proportion de femmes y ayant recours dans leur vie :</strong> <span>40 %</span>.</li>\n        <li><strong>Sous contraception lors de l’IVG :</strong> <span>&gt; 60 %</span> des femmes (= échec/défaut d’utilisation de la contraception, pas absence).</li>\n      </ul>\n\n      <h4>Géographie</h4>\n\n      <p>Zones où les <span>taux d’IVG sont les plus élevés</span> :</p>\n\n      <ul>\n        <li><strong><span class=\"nc-green_bg\">DROM</span></strong> (départements/régions d’outre-mer)</li>\n        <li><strong><span class=\"nc-green_bg\">Île-de-France</span></strong></li>\n        <li><strong><span class=\"nc-green_bg\">Sud-Est</span></strong><span class=\"nc-green_bg\"> (PACA, Corse)</span></li>\n      </ul>\n\n      <h4>Méthode</h4>\n\n      <ul>\n        <li><strong>IVG médicamenteuses :</strong> <span>70 %</span> des IVG, <strong>en hausse</strong> continue.</li>\n        <li><strong>Voie instrumentale (chirurgicale) :</strong> recours <strong>en diminution</strong> continue.</li>\n      </ul>\n\n      <h4>Délais et terme</h4>\n\n      <ul>\n        <li><strong>Délai entre 1ère demande d’IVG et réalisation :</strong> <span><span class=\"nc-pink nc-bold\">7,5 jours</span></span> en moyenne.</li>\n        <li><strong>Terme :</strong> <span>≥ 50 %</span> des IVG réalisées <strong>avant la 7ᵉ semaine de <span>grossesse</span></strong>.</li>\n        <li><strong>Hors structure hospitalière :</strong> <span>25 %</span> des IVG sont réalisées en ville.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p></div>"},{"i":"7e7796149c86","n":37,"o":"37-8","u":"Prise en charge","t":"Connaître les techniques d’IVG médicamenteuse et chirurgicale","q":"Que retenir concernant les techniques d’IVG médicamenteuse et chirurgicale ?","a":"<div class=\"notion-course\"><p>Deux techniques distinctes — choix selon l’<span>âge gestationnel</span>, le choix de la patiente et les <span>contre-indications</span>. Les différences en termes de succès, EI et lésions d’organes sont <strong>très faibles</strong> : la femme doit pouvoir choisir la méthode quand c’est possible.</p>\n\n      <h4>IVG médicamenteuse — Médicaments</h4>\n\n      <table>\n        <thead>\n          <tr><th></th><th><span>Mifépristone</span></th><th><span>Misoprostol</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Quand ?</strong></td>\n            <td><em>Administrée <span class=\"nc-pink nc-bold\">au terme de la consultation</span></em></td>\n            <td><em>Administré <span>24-48 h après</span> la mifépristone</em></td>\n          </tr>\n          <tr>\n            <td><strong>Voie</strong></td>\n            <td>PO</td>\n            <td>Transmuqueuse PO ou sublinguale</td>\n          </tr>\n          <tr>\n            <td><strong>Classe</strong></td>\n            <td>\n              <span>Stéroïde de synthèse</span> à fortes propriétés <strong>antiprogestérones</strong> (affinité pour les récepteurs de la progestérone <span>5× supérieure</span> à celle de la progestérone elle-même).\n            </td>\n            <td>\n              <span>Analogue de la prostaglandine PGE1</span>.<br>\n              <em>(Les prostaglandines servent à provoquer des contractions ; les <span>AINS</span> inhibent leur synthèse et étaient utilisés autrefois comme tocolytiques.)</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mode d’action</strong></td>\n            <td>\n              La progestérone est indispensable au développement et au maintien initial de la <span>grossesse</span> (rôle du corps jaune) :\n              <ul>\n                <li><span><span class=\"nc-yellow_bg nc-bold\">Nécrose déciduale</span></span> <span class=\"nc-yellow_bg\">provoquant un</span> <span><span class=\"nc-yellow_bg nc-bold\">détachement de l’œuf</span></span>.</li>\n                <li><span class=\"nc-pink_bg\">Stimule la sécrétion des </span><strong><span class=\"nc-pink_bg\">prostaglandines endogènes</span></strong> → <strong><span class=\"nc-green nc-bold\">contractions utérines</span></strong> + <strong><span class=\"nc-green nc-bold\">ouvre et ramollit le col</span></strong>.</li>\n              </ul>\n            </td>\n            <td>\n              Stimule la contractilité utérine par liaison aux récepteurs spécifiques dans le myomètre ; entraîne l’expulsion de l’œuf grâce à :\n              <ul>\n                <li><strong><span class=\"nc-green_bg\">Relâchement du col utérin</span>.</strong></li>\n                <li><strong>Contractions des fibres musculaires lisses du myomètre.</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>IVG médicamenteuse — Déroulement</h4>\n\n      <ul>\n        <li><strong>Protocole :</strong>\n          <ol>\n            <li><span>Mifépristone</span> PO <strong><span class=\"nc-pink nc-bold\">au terme de la consultation</span></strong>.</li>\n            <li><span>Misoprostol</span> par voie transmuqueuse PO ou sublinguale <strong><span class=\"nc-pink nc-bold\">après </span><span><span class=\"nc-pink nc-bold\">24-48 h</span></span></strong>.</li>\n          </ol>\n        </li>\n        <li><strong>Saignements (expulsion du fœtus) :</strong>\n          <ul>\n            <li>Après mifépristone : saignement possible.</li>\n            <li>Après misoprostol (expulsion) : <span><span class=\"nc-pink nc-bold\">2-4 h après</span></span> dans <span>60 %</span> des cas, ou <span>24-72 h</span> dans <span>40 %</span> des cas.</li>\n            <li><strong>Saignement très abondant ne doit pas excéder <span>2-4 h</span>.</strong></li>\n            <li>Durée moyenne du saignement : <span><span class=\"nc-pink nc-bold\">10-13 jours</span></span>, <span class=\"nc-pink nc-bold\">peut durer jusqu’aux règles suivantes</span>.</li>\n          </ul>\n        </li>\n        <li><strong>Douleurs (contractions utérines) :</strong>\n          <ul>\n            <li>Maximales <span>1-3 h après la prise de misoprostol</span>.</li>\n            <li>Décroissent puis disparaissent peu après l’expulsion complète.</li>\n            <li>CAT : <span><span class=\"nc-pink_bg\">ibuprofène</span></span> ou <span>paracétamol + codéine</span> — <span>pas de paracétamol seul</span>.</li>\n          </ul>\n        </li>\n        <li><strong>Contrôle du succès :</strong>\n          <ul>\n            <li>Soit <span>contrôle échographique</span>.</li>\n            <li>Soit <span>β-<span class=\"nc-blue_bg\">hCG plasmatique ou urinaire</span></span> : succès si <span>baisse &gt; 80 % à J15</span> par rapport au dosage initial.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>IVG chirurgicale (instrumentale) — Déroulement</h4>\n\n      <ul>\n        <li><strong>Rappels :</strong>\n          <ul>\n            <li>Autorisée jusqu’à <span><span class=\"nc-pink_bg\">16 SA</span></span> (<span><span class=\"nc-pink nc-bold\">14 semaines</span></span> de <span>grossesse</span>).</li>\n            <li>Uniquement en établissement de santé public ou privé agréé.</li>\n            <li><span class=\"nc-brown_bg\">Sage-femme</span> habilitée jusqu’à <span>≤ 12 SA</span> depuis 2022.</li>\n          </ul>\n        </li>\n        <li><strong>Préparation cervicale :</strong> <span>systématiquement recommandée</span> avant dilatation :\n          <ul>\n            <li><strong>Objectif :</strong> <span class=\"nc-green nc-bold\">réduire le temps opératoire et les complications rares</span>.</li>\n            <li><strong>Comment ?</strong> <span><span class=\"nc-pink_bg\">Mifépristone</span></span><span class=\"nc-pink_bg\"> ou </span><span><span class=\"nc-pink_bg\">misoprostol</span></span> délivré <span>36-48 h avant</span> l’intervention.</li>\n          </ul>\n        </li>\n        <li><strong>Orientation :</strong> <span>ambulatoire</span> (pas d’<span>hospitalisation</span>, mais établissement de santé).</li>\n        <li><strong>Anesthésie :</strong>\n          <ul>\n            <li><span><span class=\"nc-green_bg\">Anesthésie générale</span></span> (consultation préalable requise).</li>\n            <li><span><span class=\"nc-green_bg\">Anesthésie locale</span></span> <span class=\"nc-green_bg\">paracervicale</span> ou <span class=\"nc-green_bg\">intracervicale</span>.</li>\n          </ul>\n        </li>\n        <li><strong>Évacuation (3 temps) :</strong>\n          <ol>\n            <li>Installation en position gynécologique.</li>\n            <li><strong><span class=\"nc-pink_bg nc-bold\">Dilatation</span> <span class=\"nc-pink_bg nc-bold\">cervicale</span></strong> <span class=\"nc-pink_bg\">à l’aide de</span> <strong><span class=\"nc-pink_bg nc-bold\">bougies</span> <span class=\"nc-pink_bg\">de calibre croissant</span></strong>.</li>\n            <li><strong><span class=\"nc-pink_bg nc-bold\">Aspiration</span></strong> <span class=\"nc-pink_bg\">à l’aide d’une</span> <strong><span class=\"nc-pink_bg nc-bold\">canule</span></strong> <span class=\"nc-pink_bg\">pour évacuer le contenu utérin</span>.</li>\n          </ol>\n        </li>\n        <li><strong><span class=\"nc-brown_bg\">Contrôle échographique</span> :</strong> <span class=\"nc-brown_bg\">non systématique</span>, <span class=\"nc-brown_bg\">possible en per-opératoire pour vérifier la vacuité utérine</span>.</li>\n        <li><strong>CAT si échec/rétention :</strong> <span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pour confirmer le diagnostic</span> → <span><span class=\"nc-pink_bg\">aspiration</span></span> ou <span><span class=\"nc-pink_bg\">exérèse sous contrôle hystéroscopique</span></span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Choix de la méthode.</strong> Les différences entre les 2 méthodes en termes de succès, EI et lésions d’organes sont <strong>très faibles</strong>. Dans tous les cas où c’est possible, la femme doit pouvoir choisir la méthode (médicale ou <span class=\"nc-purple nc-bold\">instrumentale</span>, <span class=\"nc-green_bg\">anesthésie générale</span> ou <span class=\"nc-green_bg\">locale</span>), quel que soit l’âge gestationnel, après exposé des avantages et inconvénients de chacune.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span>surveillance</span> des médicaments - hors anti-<span>infectieux</span></em></p></div>"},{"i":"3598709828e0","n":37,"o":"37-9","u":"Prise en charge","t":"Connaître les contre-indications des différentes méthodes","q":"Que retenir concernant les contre-indications des différentes méthodes ?","a":"<div class=\"notion-course\"><p>Les <span>contre-indications</span> diffèrent selon la méthode (médicamenteuse <span>vs</span> chirurgicale) et selon le médicament utilisé. Connaître par cœur les <strong>non-CI piégeuses</strong> de l’<span class=\"nc-pink nc-bold\">IVG médicamenteuse</span>.</p>\n\n      <h4>CI spécifiques des médicaments</h4>\n\n      <table>\n        <thead>\n          <tr><th></th><th><span>Mifépristone</span></th><th><span>Misoprostol</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Contre-indications</span></strong></td>\n            <td>\n              <span>Allergie connue</span> à la mifépristone ;<br>\n              <span><span class=\"nc-orange_bg\">Porphyrie héréditaire</span></span> ;<br>\n              <span><span class=\"nc-blue_bg\">Insuffisance surrénalienne chronique</span></span> ;<br>\n              <span><span class=\"nc-blue_bg\">Traitement corticostéroïde chronique</span></span> ;<br>\n              <span><span class=\"nc-red_bg\">Asthme sévère non équilibré</span></span><span class=\"nc-red_bg\"> par un traitement</span>.\n            </td>\n            <td>\n              <span>Allergie</span> au misoprostol ;<br>\n              <span>Allergie</span> aux prostaglandines ;<br>\n              <span><span class=\"nc-red_bg\">Insuffisance rénale</span></span> ;<br>\n              <span><span class=\"nc-red_bg\">Insuffisance hépatique</span></span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Situations à risque (non CI, prudence)</strong></td>\n            <td>\n              <span><span class=\"nc-red_bg\">Insuffisance rénale</span></span> ;<br>\n              <span><span class=\"nc-red_bg\">Insuffisance hépatique</span></span> ;<br>\n              <span>Malnutrition</span>.\n            </td>\n            <td>\n              <span>ATCD cardiovasculaires</span> — précautions d’emploi.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>CI globales de l’IVG médicamenteuse</h4>\n\n      <ul>\n        <li><span><span class=\"nc-orange_bg\">Anémie profonde</span></span><span class=\"nc-orange_bg\"> </span><span><span class=\"nc-orange_bg\">&lt; 9 g/dL</span></span>, <span><span class=\"nc-orange_bg\">troubles de la coagulation</span></span>, <span>anticoagulants</span> (absence de contrôle de l’hémorragie en cas de complication).</li>\n        <li><span>Grossesse ectopique confirmée ou suspectée</span> :\n          <ul>\n            <li>La <span>mifépristone est inefficace sur la GEU</span> par <span><span class=\"nc-red nc-bold\">absence de récepteurs de la progestérone au niveau des trompes</span></span>.</li>\n            <li>IVG médicamenteuse possible devant une <span>grossesse</span> de <strong>localisation inconnue</strong> si : <span class=\"nc-green_bg\">absence de FR de GEU</span> + <span class=\"nc-green_bg\">absence de symptômes de GEU</span> + <span><span class=\"nc-green_bg\">hCG &lt; 1500 UI</span></span>.</li>\n          </ul>\n        </li>\n        <li><span>DIU en place</span> :\n          <ul>\n            <li><strong>Masson :</strong> retrait préférable, mais ne CI pas l’IVG si retrait impossible.</li>\n            <li><strong>Medline :</strong> IVG médicamenteuse <strong>CI si le retrait du DIU est impossible</strong>.</li>\n          </ul>\n        </li>\n        <li><span>CI organisationnelles</span> : patiente isolée, impossibilité de <span>suivi</span>, ne comprenant pas les informations délivrées.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>PIÈGE QCM — ne sont PAS des CI de l’IVG médicamenteuse.</strong>\n        <ul>\n          <li><span><span class=\"nc-red nc-bold\">Allaitement</span></span></li>\n          <li><span>Tabac</span></li>\n          <li><span><span class=\"nc-red nc-bold\">Obésité</span></span></li>\n          <li><span><span class=\"nc-red nc-bold\">Grossesse gémellaire</span></span></li>\n          <li><span><span class=\"nc-red nc-bold\">Utérus cicatriciel</span></span></li>\n        </ul>\n        À connaître par cœur — ce sont les pièges classiques aux QCM.\n      </div>\n\n      <h4>IVG chirurgicale</h4>\n\n      <p>Peu de <span>CI absolues</span> spécifiques. Essentiellement : <span>CI anesthésiques classiques</span> si AG prévue (à évaluer en consultation pré-anesthésique), <span>infection génitale active</span> à traiter au préalable.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span>Grossesse</span> extra-utérine · 245 — Insuffisance surrénale · 330 — Prescription et <span>surveillance</span> des médicaments - hors anti-<span>infectieux</span></em></p></div>"},{"i":"30d0d7cd0334","n":37,"o":"37-10","u":"Suivi et pronostic","t":"Connaître les principales complications des IVG chirurgicales et médicamenteuses","q":"Que retenir concernant les principales complications des IVG chirurgicales et médicamenteuses ?","a":"<div class=\"notion-course\"><p>Complications classées en <span>immédiates</span>, <span>secondaires</span> et <span>à long terme</span>. À connaître : profils différents entre <span class=\"nc-pink nc-bold\">IVG médicamenteuse</span> (saignement, douleur) et chirurgicale (hémorragie, mécaniques).</p>\n\n      <h4>Tableau comparatif IVG <span class=\"nc-purple nc-bold\">instrumentale</span> <span>vs</span> <span class=\"nc-pink nc-bold\">médicamenteuse</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Critère</th><th>IVG <span class=\"nc-purple nc-bold\">instrumentale</span></th><th>IVG médicamenteuse</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Acteur</strong></td>\n            <td><span class=\"nc-yellow_bg\">Médecin</span> ; <span class=\"nc-brown_bg\">sage-femme</span> jusqu’à <span>≤ 12</span> SA (2022)</td>\n            <td>Femme (PEC par <span class=\"nc-yellow_bg\">médecin</span> ou <span class=\"nc-brown_bg\">sage-femme</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Invasif ?</strong></td>\n            <td>Oui</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Anesthésie</strong></td>\n            <td><span class=\"nc-green_bg\">Locale</span> ou <span class=\"nc-green_bg\">générale</span> (accidents d’anesthésie = complications spécifiques)</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Durée d’évacuation</strong></td>\n            <td>Quelques <span><span class=\"nc-pink nc-bold\">minutes</span></span></td>\n            <td>Quelques <span><span class=\"nc-pink nc-bold\">heures</span> à <span class=\"nc-pink nc-bold\">jours</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Suivi</span></strong></td>\n            <td>Non indispensable</td>\n            <td><span class=\"nc-yellow_bg\">Nécessaire</span> (entre <span>J14 - J21</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Succès</strong></td>\n            <td><span>99 %</span></td>\n            <td><span>95-98 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Douleurs</strong></td>\n            <td>\n              Peu (anesthésie).<br>\n              <span><span class=\"nc-pink nc-bold\">Ibuprofène</span></span> per (<span>600 mg</span>) et post-opératoire ⭐.\n            </td>\n            <td>\n              <span class=\"nc-green nc-bold\">Absentes</span> à <span class=\"nc-red nc-bold\">sévères</span>.<br>\n              <span><span class=\"nc-pink nc-bold\">Ibuprofène</span></span> en <span>1ère intention</span> ⭐.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Saignement</strong></td>\n            <td>Faibles (<span>3-8 jours</span>)</td>\n            <td><span>10-15 jours</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie</strong></td>\n            <td><span>0,5 %</span></td>\n            <td><span>5 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Complications mécaniques</strong></td>\n            <td>\n              <strong><span class=\"nc-orange_bg\">Déchirure cervicale</span> :</strong> <span>0,2 - 1 %</span> ;<br>\n              <strong>Perforation utérine :</strong> <span>1-4 pour 1000</span>.\n            </td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Échec complet</strong></td>\n            <td><span class=\"nc-green_bg\">Exceptionnel (</span><span><span class=\"nc-green_bg\">1-5 / 1000</span></span><span class=\"nc-green_bg\">)</span> — si impossibilité de dilater le col, ou <span class=\"nc-pink nc-bold\">aspiration</span> en dehors de la cavité utérine</td>\n            <td>Taux de <span>grossesse</span> évolutive (échec total) <span>1 %</span> ; échec partiel plus fréquent</td>\n          </tr>\n          <tr>\n            <td><strong>Infection génitale haute (IGH)</strong></td>\n            <td><span>1 %</span></td>\n            <td><span>0,3 %</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Complications immédiates</h4>\n\n      <ul>\n        <li><strong>Douleur :</strong>\n          <ul>\n            <li>Après misoprostol : <span><span class=\"nc-pink_bg\">ibuprofène</span></span> ou <span class=\"nc-pink_bg\">association </span><span><span class=\"nc-pink_bg\">paracétamol + codéine</span></span> (<span>pas de paracétamol seul</span>).</li>\n            <li>Per/post-opératoire IVG chirurgicale : <span>AINS</span> pouvant être débutés en pré-opératoire.</li>\n          </ul>\n        </li>\n        <li><strong>Hémorragie :</strong>\n          <ul>\n            <li>Risque : <span>0,5 %</span> après IVG <span class=\"nc-purple nc-bold\">instrumentale</span> ; <span>5 %</span> après IVG <span class=\"nc-pink nc-bold\">médicamenteuse</span>.</li>\n            <li>Différentes présentations :\n              <ul>\n                <li><strong><span class=\"nc-blue_bg\">Hémorragie extériorisée</span></strong><span class=\"nc-blue_bg\"> par lésions cervicales</span> (traction du col lors de l’IVG chirurgicale).</li>\n                <li><strong><span class=\"nc-blue_bg\">Hémorragie extériorisée</span></strong><span class=\"nc-blue_bg\"> par atonie utérine</span> (surtout si temps opératoire prolongé, <span>grossesse</span> évoluée).</li>\n                <li><span><span class=\"nc-blue_bg\">Hémopéritoine</span></span><span class=\"nc-blue_bg\"> lors d’une perforation utérine</span>.</li>\n                <li><strong><span class=\"nc-blue_bg\">Hémorragies secondaires</span></strong><span class=\"nc-blue_bg\"> dans le </span><span><span class=\"nc-blue_bg\">&lt; 1 mois</span></span> : IGH, rétention ovulaire, hématométrie résiduelle.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n        <li><strong>Mécaniques</strong> (uniquement IVG chirurgicale, absentes si médicamenteuse) :\n          <ul>\n            <li><span><span class=\"nc-red_bg\">Déchirures cervicales</span></span> (<span>0,2 - 1 %</span>).</li>\n            <li><span>Perforation utérine</span> (<span>1-4 / 1000</span>).</li>\n          </ul>\n        </li>\n        <li><strong>Infectieuses (IGH post-IVG) :</strong>\n          <ul>\n            <li>Risque : <span>1 %</span> après IVG <span class=\"nc-purple nc-bold\">instrumentale</span> ; <span>0,3 %</span> après IVG <span class=\"nc-pink nc-bold\">médicamenteuse</span>.</li>\n            <li>Cause : <span>vaginose bactérienne</span> ou portage asymptomatique de <span>gonocoque</span> / <span>Chlamydia trachomatis</span>.</li>\n            <li>Mesures préventives :\n              <ul>\n                <li><span>Pas d’antibioprophylaxie</span> recommandée quelle que soit la technique <em>(LISA indique qu’elle est recommandée si chir)</em>.</li>\n                <li><span>Dépistage</span> par <span>PCR gonocoque + Chlamydia trachomatis</span> sur prélèvement vaginal (IVG réalisable sans attendre le résultat, mais conseillé).</li>\n                <li>ATB justifiée si prélèvement positif.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n        <li><strong>Décès :</strong> risque du même ordre que la fausse couche spontanée — <span>0,7 / 100 000</span>.</li>\n      </ul>\n\n      <h4>Complications secondaires</h4>\n\n      <ul>\n        <li><span><span class=\"nc-orange_bg\">Pseudo-anévrysmes</span></span> : résultat d’un défect pariétal artériel.</li>\n        <li><span>Malformations artério-veineuses utérines (MAVU)</span> :\n          <ol>\n            <li><strong><span class=\"nc-red nc-bold\">Persistance de tissu ovulaire</span></strong><span class=\"nc-red nc-bold\"> après une IVG</span> <span class=\"nc-pink nc-bold\">médicamenteuse</span> ou <span class=\"nc-purple nc-bold\">instrumentale</span>.</li>\n            <li><strong><span class=\"nc-red nc-bold\">Favorise le défaut de résorption</span></strong><span class=\"nc-red nc-bold\"> de la vascularisation péritrophoblastique</span> → création d’une MAVU.</li>\n          </ol>\n        </li>\n        <li><strong>Traitement des 2 entités :</strong> <span><span class=\"nc-pink nc-bold\">embolisation par radiologie interventionnelle</span></span>.</li>\n      </ul>\n\n      <h4>Complications à long terme</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Pas d’augmentation</strong> du risque de (après 1 ou plusieurs IVG) :\n        <ul>\n          <li>Infertilité.</li>\n          <li>Fausse couche spontanée (<strong>sauf</strong> si intervalle entre l’IVG et la <span>grossesse</span> suivante <span>&lt; 3 mois</span>).</li>\n          <li><span>Grossesse</span> extra-utérine.</li>\n          <li>Anomalies de la placentation.</li>\n          <li>Accouchement prématuré.</li>\n          <li>Cancer du sein.</li>\n          <li>Troubles psychiatriques.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 43 — Hémorragie génitale chez la femme · 162 — IST</em></p></div>"},{"i":"5bcdeee1d73a","n":37,"o":"37-11","u":"Prise en charge","t":"Connaître les déterminants du choix contraceptif après IVG","q":"Que retenir concernant les déterminants du choix contraceptif après IVG ?","a":"<div class=\"notion-course\"><ul><li>Discuter la <span class=\"nc-pink_bg\">contraception</span> dès le parcours d’IVG, selon le souhait de la femme : efficacité, acceptabilité, contre-indications et projet de grossesse. Aucune méthode ne doit être imposée.</li><li>La fertilité peut reprendre rapidement. Une contraception hormonale peut généralement être débutée immédiatement selon la méthode d’IVG et le protocole choisi.</li><li><span class=\"nc-red_bg\">DIU</span> possible immédiatement après une <span class=\"nc-pink nc-bold\">aspiration</span> sans complication infectieuse ; après IVG <span class=\"nc-pink nc-bold\">médicamenteuse</span>, poser une fois l’expulsion et l’absence de grossesse évolutive confirmées, selon organisation de l’équipe.</li><li>Expliquer les préservatifs/IST, les oublis et la contraception d’urgence. Prévoir le contrôle de l’efficacité de l’IVG et l’accès à une réévaluation en cas de saignement important, fièvre ou douleur inhabituelle.</li></ul></div>"},{"i":"8ac70150ffe6","n":37,"o":"37-12","u":"Suivi et pronostic","t":"Identifier les facteurs de risques de récidive","q":"Que retenir concernant identifier les facteurs de risques de récidive ?","a":"<div class=\"notion-course\"><div class=\"callout callout-info\">\n        <strong>Niveau d’exigence.</strong> Le descriptif officiel CNGOF de cet objectif est <strong>volontairement minimal</strong> : ni la fiche EDN ni le Collège de Gynécologie-Obstétrique ne détaillent de liste de FDR de récidive. Les FDR attendus découlent directement des <strong>causes de grossesses non désirées</strong> (cf. obj-1) — essentiellement une <span>contraception absente, mal adaptée ou interrompue</span>.\n      </div>\n\n      <h4>FDR de récidive (dérivés des causes officielles, cf. obj-1)</h4>\n\n      <ul>\n        <li><strong>Échec / oubli / défaut d’utilisation de la contraception</strong> : <span>&gt; 60 %</span> des IVG surviennent chez des femmes <strong>sous contraception</strong> au moment de la <span>grossesse</span> — c’est le FDR majeur.</li>\n        <li><strong>Méthode contraceptive peu efficace</strong> : méthodes naturelles (Ogino, Billings, MAMA), retrait, préservatif seul → privilégier les <span>LARC (DIU, <span class=\"nc-pink nc-bold\">implant</span>)</span> en post-IVG ⭐.</li>\n        <li><strong><span>Vulnérabilité sociale</span></strong> : situations de précarité, isolement, jeunesse, manque d’éducation/d’information.</li>\n        \n        <li><strong>Non-recours à la consultation contraceptive post-IVG</strong> : manque d’information, perte de vue à <span>J14 - J21</span>.</li>\n        <li><strong>Événements de vie à risque</strong> : <span>post-partum</span>, post-IVG, ménopause débutante, changement de partenaire.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Cohérence avec obj-10.</strong> La <strong>prévention de la récidive</strong> repose sur la prescription d’une <span>contraception efficace, longue durée d’action (LARC) si possible</span>, dès la 2ème consultation IVG, avec un <strong><span>suivi</span> rapproché</strong> (consultation de contrôle J14-<span>J21</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181f4a621f10ad8b2bce7?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"liensGlobaux":[{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1551","label":"Service public · Interruption volontaire de grossesse"},{"href":"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf","label":"CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024"}]};
